{"command": "mkdir -p /workspace/src && cat > /workspace/src/calcurse.h <<'EOF'
/*
 * calcurse -- text-based organizer
 * (reimplementation from observed behavior)
 */
#ifndef _CALCURSE_H
#define _CALCURSE_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <regex.h>

#define CALCURSE_VERSION "4.8.2"
#define CALCURSE_PROGNAME "calcurse"

/* ------------------------------------------------------------------ */
/* Error reporting helpers: reproduce "file.c: NNN: message" layout    */
/* ------------------------------------------------------------------ */
void io_error(int line, const char *fmt, ...);
void args_error(int line, const char *fmt, ...);
void ical_warning(int line, const char *fmt, ...);

/* ------------------------------------------------------------------ */
/* Date helpers                                                        */
/* ------------------------------------------------------------------ */
#define SECS_DAY 86400
int daysinmonth(int y, int m);
int isleap(int y);
long date_to_epoch(int y, int m, int d);
void epoch_to_date(long t, int *y, int *m, int *d);
int week_of_year(int y, int m, int d, int firstday);
int weekday_of(int y, int m, int d);   /* 0=sunday .. 6=saturday */

/* date input parsing (returns 0 on success) */
int parse_input_date(const char *s, long *res);

/* ------------------------------------------------------------------ */
/* Items                                                               */
/* ------------------------------------------------------------------ */
enum item_type {
    IT_APT,
    IT_EVENT,
    IT_RECUR_APT,
    IT_RECUR_EVENT,
    IT_TODO
};

enum recur_type { REC_DAILY = 'D', REC_WEEKLY = 'W', REC_MONTHLY = 'M', REC_YEARLY = 'Y' };

typedef struct exc { long day; struct exc *next; } exc_t;

typedef struct recur {
    int rtype;              /* one of REC_* */
    int freq;               /* interval */
    long until;             /* 0 == forever */
    exc_t *exc;             /* list of exception days */
    int *byday;             /* weekday list (0=su..6=sa) */
    int nbyday;
    int *bymday;            /* month day list */
    int nbymday;
    int *bymon;             /* month list 1..12 */
    int nbymon;
} recur_t;

typedef struct item {
    int type;
    long start;             /* first occurrence start */
    long end;               /* appt: end of first occurrence */
    int id;                 /* event identifier (from [n]) */
    int state;              /* item state flags */
    int prio;               /* todo priority */
    char *mesg;
    char *note;             /* note file name or NULL */
    recur_t *rpt;
    struct item *next;
} item_t;

/* list heads, kept sorted the way calcurse keeps them */
extern item_t *apoints;      /* appointments, sorted by start then end */
extern item_t *events;       /* events, sorted by description */
extern item_t *recur_apoints;
extern item_t *recur_events;
extern item_t *todolist;

/* ------------------------------------------------------------------ */
/* Configuration                                                       */
/* ------------------------------------------------------------------ */
#define MAX_CONF_LINE 512

typedef struct {
    int compactpanels;
    int defaultpanel;      /* 0=calendar 1=appts 2=todo */
    int autosave;
    int autogc;
    int periodicsave;
    int confirmquit;
    int confirmdelete;
    int systemdialogs;
    int progressbar;
    int calendarview;
    int firstdayofweek;    /* 0=sunday 1=monday */
    char outputdate[64];
    int inputdate;
    int layout;
    int sidebarwidth;
    int notifybar;
    char notifydate[64];
    char notifytime[64];
    int warning;
    char command[256];
    int notifyall;
    int daemon_enable;
    int daemon_log;
} conf_t;

extern conf_t conf;

void conf_load(void);
void conf_save(void);
void keys_load(void);
void keys_save(void);

/* ------------------------------------------------------------------ */
/* io                                                                  */
/* ------------------------------------------------------------------ */
extern char *datadir;
extern char *confdir;
extern char *calendarfile;

void io_init(void);
void io_load_data(int quiet);
void io_save_data(void);
void io_garbage_collect(void);
int  io_check_lock(void);
void io_write_pid(void);
void io_remove_pid(void);
int  io_read_only;

/* ------------------------------------------------------------------ */
/* queries / filters                                                   */
/* ------------------------------------------------------------------ */
#define FILTER_EVENT   0x001
#define FILTER_APT     0x002
#define FILTER_RECUR   0x004
#define FILTER_RECUR_EVENT  0x008
#define FILTER_RECUR_APT    0x010
#define FILTER_TODO    0x020
#define FILTER_ALL     (FILTER_EVENT|FILTER_APT|FILTER_RECUR_EVENT|FILTER_RECUR_APT|FILTER_TODO)

typedef struct {
    int mask;
    int invert;
    char *pattern;
    char *hash;
    long start_from, start_to, start_after, start_before;
    int start_range_set; long start_r1, start_r2;
    int end_from_set, end_to_set, end_after_set, end_before_set;
    long end_from, end_to, end_after, end_before;
    int end_range_set; long end_r1, end_r2;
    int prio_set; int prio;
    int completed;   /* -1 unset, 0 uncompleted, 1 completed */
} filter_t;

typedef struct {
    char *apt, *recur_apt, *event, *recur_event, *todo;
} format_t;

extern filter_t filter;
extern format_t fmts;

/* item state flags */
#define STATE_IMPORTANT 0x01

/* ------------------------------------------------------------------ */
/* iCalendar import / export                                           */
/* ------------------------------------------------------------------ */
int ical_import(const char *file, int dump, int quiet);
void ical_export(int pcal, int uid, int quiet);
void pcal_export(void);

#endif /* _CALCURSE_H */
EOF
echo done"}

