/* helper: strip a trailing hh:mm from a filter date argument */
static long parse_filter_date(const char *s, int line)
{
    char buf[128];
    char *p;
    long res;
    long t = 0;

    if (!s)
        return -1;
    strncpy(buf, s, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    if ((p = strchr(buf, ' ')) != NULL)
        *p = '\0';
    if (parse_input_date(buf, &res) < 0)
        args_error(line, "invalid date: %s", s);
    /* optional time of day */
    if (p != NULL) {
        int h, m;
        if (sscanf(p + 1, "%d:%d", &h, &m) != 2 || h < 0 || h > 23 || m < 0 || m > 59)
            args_error(line, "invalid date: %s", s);
        t = h * 3600 + m * 60;
    }
    return res + t;
}

static void set_filter_type(const char *s)
{
    char buf[256], *tok, *save = NULL;
    int mask = 0;

    strncpy(buf, s, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    for (tok = strtok_r(buf, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
        if (!strcmp(tok, "event"))
            mask |= FILTER_EVENT;
        else if (!strcmp(tok, "apt"))
            mask |= FILTER_APT;
        else if (!strcmp(tok, "recur"))
            mask |= FILTER_RECUR_EVENT | FILTER_RECUR_APT;
        else if (!strcmp(tok, "recur-event"))
            mask |= FILTER_RECUR_EVENT;
        else if (!strcmp(tok, "recur-apt"))
            mask |= FILTER_RECUR_APT;
        else if (!strcmp(tok, "cal"))
            mask |= FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT;
        else if (!strcmp(tok, "todo"))
            mask |= FILTER_TODO;
        else
            args_error(ERR_FILTER_MASK, "invalid filter mask");
    }
    if (mask == 0)
        args_error(ERR_FILTER_MASK, "invalid filter mask");
    filter.mask = mask;
}

static void set_filter_range(const char *s, long *a, long *b, int line)
{
    char buf[256], *p;
    strncpy(buf, s, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    if ((p = strchr(buf, ',')) == NULL)
        args_error(line, "invalid date range: %s", s);
    *p = '\0';
    if (parse_input_date(buf, a) < 0)
        args_error(line, "invalid date range: %s", s);
    if (parse_input_date(p + 1, b) < 0)
        args_error(line, "invalid date range: %s", s);
}

static void parse_search(const char *s)
{
    int r = regcomp(&args.search_re, s, REG_EXTENDED | REG_NOSUB);
    if (r != 0)
        args_error(ERR_SEARCH, "could not compile regular expression: %s", s);
    args.search_compiled = 1;
}

void args_parse(int argc, char **argv)
{
    static struct option longopts[] = {
        {"query",                no_argument,       NULL, 'Q'},
        {"appointment",          no_argument,       NULL, 'a'},
        {"day",                  required_argument, NULL, 'd'},
        {"next",                 no_argument,       NULL, 'n'},
        {"range",                optional_argument, NULL, 'r'},
        {"startday",             optional_argument, NULL, 's'},
        {"todo",                 optional_argument, NULL, 't'},
        {"grep",                 no_argument,       NULL, 'G'},
        {"purge",                no_argument,       NULL, 'P'},
        {"gc",                   no_argument,       NULL, 'g'},
        {"help",                 no_argument,       NULL, 'h'},
        {"version",              no_argument,       NULL, 'v'},
        {"status",               no_argument,       NULL, 900},
        {"daemon",               no_argument,       NULL, 901},
        {"import",               required_argument, NULL, 'i'},
        {"export",               optional_argument, NULL, 'x'},
        {"calendar",             required_argument, NULL, 'c'},
        {"confdir",              required_argument, NULL, 'C'},
        {"datadir",              required_argument, NULL, 'D'},
        {"quiet",                no_argument,       NULL, 'q'},
        {"read-only",            no_argument,       NULL, 902},
        {"limit",                required_argument, NULL, 'l'},
        {"search",               required_argument, NULL, 'S'},
        {"from",                 required_argument, NULL, 903},
        {"to",                   required_argument, NULL, 904},
        {"days",                 required_argument, NULL, 905},
        {"dump-imported",        no_argument,       NULL, 906},
        {"export-uid",           no_argument,       NULL, 907},
        {"input-datefmt",        required_argument, NULL, 908},
        {"output-datefmt",       required_argument, NULL, 909},
        {"filter-type",          required_argument, NULL, 910},
        {"filter-pattern",       required_argument, NULL, 911},
        {"filter-hash",          required_argument, NULL, 912},
        {"filter-start-from",    required_argument, NULL, 913},
        {"filter-start-to",      required_argument, NULL, 914},
        {"filter-start-after",   required_argument, NULL, 915},
        {"filter-start-before",  required_argument, NULL, 916},
        {"filter-start-range",   required_argument, NULL, 917},
        {"filter-end-from",      required_argument, NULL, 918},
        {"filter-end-to",        required_argument, NULL, 919},
        {"filter-end-after",     required_argument, NULL, 920},
        {"filter-end-before",    required_argument, NULL, 921},
        {"filter-end-range",     required_argument, NULL, 922},
        {"filter-priority",      required_argument, NULL, 923},
        {"filter-completed",     no_argument,       NULL, 924},
        {"filter-uncompleted",   no_argument,       NULL, 925},
        {"filter-invert",        no_argument,       NULL, 926},
        {"format-apt",           required_argument, NULL, 927},
        {"format-recur-apt",     required_argument, NULL, 928},
        {"format-event",         required_argument, NULL, 929},
        {"format-recur-event",   required_argument, NULL, 930},
        {"format-todo",          required_argument, NULL, 931},
        {NULL, 0, NULL, 0}
    };
    const char *optstr = ":Qad:nr::s::t::GPghvi:x::c:C:D:ql:S:";
    int c, n;
    int f_used = 0, fmt_used = 0, range_used = 0;

    memset(&args, 0, sizeof(args));
    args.op = OP_NONE;
    filter.mask = FILTER_ALL;
    filter.completed = -1;
    fmts.apt = DEF_FMT_APT;
    fmts.recur_apt = DEF_FMT_RECUR_APT;
    fmts.event = DEF_FMT_EVENT;
    fmts.recur_event = DEF_FMT_RECUR_EVENT;
    fmts.todo = DEF_FMT_TODO;

    optind = 0;
    opterr = 0;
    while ((c = getopt_long(argc, argv, optstr, longopts, NULL)) != -1) {
        switch (c) {
        case 'Q':
            args.op = OP_QUERY; args.op_set = 1; break;
        case 'a':
            args.op = OP_APPOINT; args.op_set = 1;
            filter.mask |= FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT;
            break;
        case 'd':
            args.op = OP_DAY; args.op_set = 1; args.day_set = 1;
            if (parse_input_date(optarg, &args.day) < 0) {
                char *p;
                args.day_is_date = 0;
                args.day = strtol(optarg, &p, 10);
                if (*p != '\0' || p == optarg)
                    args_error(ERR_DAY_DATE, "invalid date: %s", optarg);
                if (args.day == 0)
                    args_error(ERR_DAY_RANGE, "invalid range: 0");
            } else {
                args.day_is_date = 1;
            }
            filter.mask |= FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT;
            break;
        case 'n':
            args.op = OP_NEXT; args.op_set = 1; break;
        case 'r':
            args.op = OP_RANGE; args.op_set = 1;
            args.range_set = 1;
            if (optarg == NULL)
                args.range = 1;
            else {
                char *p;
                args.range = strtol(optarg, &p, 10);
                if (*p != '\0' || p == optarg)
                    args_error(ERR_RANGE_RANGE, "invalid range: %s", optarg);
                if (args.range == 0)
                    args_error(ERR_RANGE_RANGE, "invalid range: 0");
            }
            filter.mask |= FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT;
            break;
        case 's':
            args.op = OP_STARTDAY; args.op_set = 1;
            if (optarg != NULL) {
                if (parse_input_date(optarg, &args.from) < 0)
                    args_error(ERR_FROM_DATE, "invalid date: %s", optarg);
                args.from_set = 1;
            }
            filter.mask |= FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT;
            break;
        case 't':
            args.op = OP_TODO; args.op_set = 1;
            filter.mask |= FILTER_TODO;
            if (optarg != NULL) {
                if (!strcmp(optarg, "0")) {
                    args.todo_prio_set = 1;
                    args.todo_completed = 1;
                    filter.completed = 1;
                } else {
                    char *p;
                    args.priority = (int)strtol(optarg, &p, 10);
                    if (*p != '\0' || p == optarg || args.priority < 1 || args.priority > 9)
                        args_error(ERR_TODO_PRIO, "invalid priority: %s", optarg);
                    args.todo_prio_set = 1;
                    args.todo_completed = 0;
                    filter.prio_set = 1;
                    filter.prio = args.priority;
                    filter.completed = 0;
                }
            } else {
                filter.completed = 0;
            }
            break;
        case 'G':
            args.op = OP_GREP; args.op_set = 1; break;
        case 'P':
            args.op = OP_PURGE; args.op_set = 1; break;
        case 'g':
            args.op = OP_GC; args.op_set = 1; break;
        case 'h':
            args.op = OP_HELP; args.op_set = 1; break;
        case 'v':
            args.op = OP_VERSION; args.op_set = 1; break;
        case 'i':
            args.op = OP_IMPORT; args.op_set = 1; args.import_file = optarg; break;
        case 'x':
            args.op = OP_EXPORT; args.op_set = 1;
            if (optarg != NULL) {
                if (!strcmp(optarg, "ical"))
                    args.export_format = 0;
                else if (!strcmp(optarg, "pcal"))
                    args.export_format = 1;
                else
                    args_error(ERR_EXPORT_FMT, "invalid export format: %s", optarg);
            }
            break;
        case 'c':
            calendarfile = optarg; break;
        case 'C':
            confdir = optarg; break;
        case 'D':
            datadir = optarg; break;
        case 'q':
            args.quiet = 1; break;
        case 'l':
            args.limit_set = 1;
            args.limit = strtol(optarg, NULL, 10);
            break;
        case 'S':
            parse_search(optarg);
            f_used = 1;
            break;
        case 900: args.op = OP_STATUS; args.op_set = 1; break;
        case 901: args.op = OP_DAEMON; args.op_set = 1; break;
        case 902: args.read_only = 1; break;
        case 903:
            args.from = parse_filter_date(optarg, ERR_FROM_DATE);
            args.from_set = 1; range_used = 1; break;
        case 904:
            args.to = parse_filter_date(optarg, ERR_FROM_DATE);
            args.to_set = 1; range_used = 1; break;
        case 905:
            if (!strcmp(optarg, "0")) {
                args.days = 0;
            } else {
                char *p;
                args.days = strtol(optarg, &p, 10);
                if (*p != '\0' || p == optarg)
                    args_error(ERR_DAYS_RANGE, "invalid range: %s", optarg);
                if (args.days == 0)
                    args_error(ERR_DAYS_RANGE, "invalid range: 0");
            }
            args.days_set = 1; range_used = 1; break;
        case 906: args.dump_imported = 1; break;
        case 907: args.export_uid = 1; break;
        case 908:
            n = atoi(optarg);
            if (n < 1 || n > 4 || strlen(optarg) != 1 || !isdigit((unsigned char)optarg[0]))
                args_error(ERR_INPUT_DATEFMT, "invalid input date format: %s", optarg);
            conf.inputdate = n;
            args.input_datefmt_set = 1;
            break;
        case 909:
            strncpy(conf.outputdate, optarg, sizeof(conf.outputdate) - 1);
            args.output_datefmt_set = 1;
            break;
        case 910: set_filter_type(optarg); f_used = 1; break;
        case 911:
            filter.pattern = optarg; f_used = 1; break;
        case 912: filter.hash = optarg; f_used = 1; break;
        case 913: filter.start_from = parse_filter_date(optarg, ERR_FILTER_DATE); f_used = 1; break;
        case 914: filter.start_to = parse_filter_date(optarg, ERR_FILTER_DATE); f_used = 1; break;
        case 915: filter.start_after = parse_filter_date(optarg, ERR_FILTER_DATE); f_used = 1; break;
        case 916: filter.start_before = parse_filter_date(optarg, ERR_FILTER_DATE); f_used = 1; break;
        case 917:
            set_filter_range(optarg, &filter.start_r1, &filter.start_r2, ERR_FILTER_RANGE);
            filter.start_range_set = 1; f_used = 1; break;
        case 918: filter.end_from = parse_filter_date(optarg, ERR_FILTER_DATE);
                  filter.end_from_set = 1; f_used = 1; break;
        case 919: filter.end_to = parse_filter_date(optarg, ERR_FILTER_DATE);
                  filter.end_to_set = 1; f_used = 1; break;
        case 920: filter.end_after = parse_filter_date(optarg, ERR_FILTER_DATE);
                  filter.end_after_set = 1; f_used = 1; break;
        case 921: filter.end_before = parse_filter_date(optarg, ERR_FILTER_DATE);
                  filter.end_before_set = 1; f_used = 1; break;
        case 922:
            set_filter_range(optarg, &filter.end_r1, &filter.end_r2, ERR_FILTER_END_RANGE);
            filter.end_range_set = 1; f_used = 1; break;
        case 923:
            n = atoi(optarg);
            if (n < 0 || n > 9 || strlen(optarg) > 1 || !isdigit((unsigned char)optarg[0]))
                args_error(ERR_PRIO, "invalid priority: %s", optarg);
            filter.prio_set = 1; filter.prio = n; f_used = 1; break;
        case 924: filter.completed = 1; f_used = 1; break;
        case 925: filter.completed = 0; f_used = 1; break;
        case 926: filter.invert = 1; f_used = 1; break;
        case 927: fmts.apt = optarg; fmt_used = 1; break;
        case 928: fmts.recur_apt = optarg; fmt_used = 1; break;
        case 929: fmts.event = optarg; fmt_used = 1; break;
        case 930: fmts.recur_event = optarg; fmt_used = 1; break;
        case 931: fmts.todo = optarg; fmt_used = 1; break;
        case '?':
        case ':':
            fprintf(stderr, "%s: %s\n", CALCURSE_PROGNAME, optopt ? optopt : "");
            fputs(usage_text, stderr);
            exit(1);
