void epoch_to_date(long t, int *y, int *m, int *d);
long day_of_epoch(int y, int m, int d);   /* days since 1970-01-01 (midnight) */
void day_to_date(long n, int *y, int *m, int *d);
int week_of_year(int y, int m, int d, int firstday);
int tm2epoch(int y, int m, int d, int h, int mi, int s);

/* input date parsing according to conf.inputdate; returns 0 on success */
int parse_input_date(const char *s, long *res);
int parse_date_str(const char *s, int *y, int *m, int *d);

/* output date formatting: understands calcurse's %D/%F plus strftime */
void fmt_date(long t, char *buf, size_t sz, const char *fmt);
void date_str(char *buf, size_t sz, long t);   /* uses conf.outputdate */

