EOF
cat > /workspace/src/dates.c <<'CEOF'
#include "calcurse.h"
#include "dates.h"

int isleap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

int daysinmonth(int y, int m)
{
    static const int dm[13] = { 0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (m == 2 && isleap(y))
        return 29;
    return dm[m];
}

int weekday_of(int y, int m, int d)
{
    long n = day_of_epoch(y, m, d);
    int w = (int)((n + 4) % 7);   /* 1970-01-01 was a Thursday */
    if (w < 0)
        w += 7;
    return w;
}

/* days since 1970-01-01, proleptic Gregorian */
long day_of_epoch(int y, int m, int d)
{
    long a = (14 - m) / 12;
    long yy = y + 4800 - a;
    long mm = m + 12 * a - 3;
    long j = d + (153 * mm + 2) / 5 + 365L * yy + yy / 4 - yy / 100 + yy / 400 - 32045;
    return j - 2440588;
}

void day_to_date(long n, int *y, int *m, int *d)
{
    long j = n + 2440588;
    long a = j + 32044;
    long b = (4 * a + 3) / 146097;
    long c = a - 146097 * b / 4;
    long dd = (4 * c + 3) / 1461;
    long e = c - 1461 * dd / 4;
    long mm = (5 * e + 2) / 153;
    *d = (int)(e - (153 * mm + 2) / 5 + 1);
    *m = (int)(mm + 3 - 12 * (mm / 10));
    *y = (int)(100 * b + dd - 4800 + mm / 10);
}

long date_to_epoch(int y, int m, int d)
{
    return day_of_epoch(y, m, d) * SECS_DAY;
}

void epoch_to_date(long t, int *y, int *m, int *d)
{
    day_to_date(t / SECS_DAY, y, m, d);
}

int tm2epoch(int y, int m, int d, int h, int mi, int s)
{
    return (int)(date_to_epoch(y, m, d) + h * 3600 + mi * 60 + s);
}

int week_of_year(int y, int m, int d, int firstday)
{
    /* firstday: 0 = Sunday, 1 = Monday */
    long dn = day_of_epoch(y, m, d);
    long jan1 = day_of_epoch(y, 1, 1);
    int wd_jan1 = (int)((jan1 + 4) % 7);
    int off;
    if (wd_jan1 < 0)
        wd_jan1 += 7;
    if (firstday == 1) {
        /* monday-first: monday = 0 */
        off = (wd_jan1 + 6) % 7;
    } else {
        off = wd_jan1;
    }
    return (int)((dn - jan1 + off) / 7) + 1;
}

/* --------------------------------------------------------------- */
/* input date parsing                                              */
/* --------------------------------------------------------------- */
int parse_date_str(const char *s, int *y, int *m, int *d)
{
    int n, mth, day, year;
    int ok = 0;

    if (!s || !*s)
        return -1;
    /* keywords first */
    if (!strcasecmp(s, "today") || !strcasecmp(s, "now")) {
        long t = time(NULL);
        epoch_to_date(t, y, m, d);
        return 0;
    }
    if (!strcasecmp(s, "tomorrow")) {
