{"command": "cat > /workspace/src/io.c <<'CEOF'
#define _GNU_SOURCE
#include "calcurse.h"
#include "io.h"
#include "dates.h"
#include <stdarg.h>
#include <ctype.h>

int readonly_flag = 0;

item_t *apoints;
item_t *events;
item_t *recur_apoints;
item_t *recur_events;
item_t *todolist;

/* ------------------------------------------------------------------ */
/* error reporting                                                     */
/* ------------------------------------------------------------------ */
static void verr(const char *file, int line, const char *fmt, va_list ap)
{
    fprintf(stderr, "%s: %d: ", file, line);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
}

void io_error(int line, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    verr("io.c", line, fmt, ap);
    va_end(ap);
}

void recur_error(int line, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    verr("recur.c", line, fmt, ap);
    va_end(ap);
}

void ical_warning(int line, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    verr("ical.c", line, fmt, ap);
    va_end(ap);
}

/* ------------------------------------------------------------------ */
/* items                                                               */
/* ------------------------------------------------------------------ */
item_t *item_new(int type)
{
    item_t *p = calloc(1, sizeof(item_t));
    p->type = type;
    p->id = 1;
    return p;
}

void item_free(item_t *p)
{
    exc_t *e, *n;
    if (!p)
        return;
    free(p->mesg);
    free(p->note);
    if (p->rpt) {
        for (e = p->rpt->exc; e; e = n) {
            n = e->next;
            free(e);
        }
        free(p->rpt->byday);
        free(p->rpt->bymday);
        free(p->rpt->bymon);
        free(p->rpt);
    }
    free(p);
}

/* sort key: (start, description) */
static int item_before(item_t *a, item_t *b)
{
    if (a->start < b->start)
        return 1;
    if (a->start > b->start)
        return 0;
    if (a->mesg && b->mesg)
        return strcmp(a->mesg, b->mesg) < 0;
    return 0;
}

void item_insert(item_t *it)
{
    item_t **head, **pp;
    switch (it->type) {
    case IT_APT:         head = &apoints;        break;
    case IT_EVENT:       head = &events;         break;
    case IT_RECUR_APT:   head = &recur_apoints;  break;
    case IT_RECUR_EVENT: head = &recur_events;   break;
    default:             head = &todolist;       break;
    }
    if (it->type == IT_TODO) {
        item_t **p;
        int key(int v) { return v > 0 ? 0 : 1; }
        for (p = head; *p; p = &(*p)->next) {
            int ka = key(it->prio), kb = key((*p)->prio);
            if (ka < kb)
                break;
            if (ka == kb) {
                int va = it->prio > 0 ? it->prio : -it->prio;
                int vb = (*p)->prio > 0 ? (*p)->prio : -(*p)->prio;
                if (va < vb)
                    break;
            }
        }
        it->next = *p;
        *p = it;
        return;
    }
    for (pp = head; *pp; pp = &(*pp)->next)
        if (item_before(it, *pp))
            break;
    it->next = *pp;
    *pp = it;
}

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */
static char *xstrdup(const char *s)
{
    return s ? strdup(s) : NULL;
}

static int is_leap(int y) { return isleap(y); }

/* parse "MM/DD/YYYY" using input date format 1 (data files always use it) */
static int parse_data_date(const char *s, long *res)
{
    int y, m, d;
    if (sscanf(s, "%d/%d/%d", &m, &d, &y) != 3)
        return -1;
    /* the separators must really be '/' */
    {
        const char *p = s;
        int n1 = 0, n2 = 0;
        while (*p && isdigit((unsigned char)*p)) { p++; n1++; }
        if (*p != '/') return -1;
        p++;
        while (*p && isdigit((unsigned char)*p)) { p++; n2++; }
        if (*p != '/') return -1;
        p++;
        if (!isdigit((unsigned char)*p)) return -1;
        while (*p && isdigit((unsigned char)*p)) p++;
        if (*p != '\0') return -1;
        if (n1 > 2 || n2 > 2) return -1;
    }
    if (m < 1 || m > 12 || d < 1 || d > 31 || y < 1)
        return -1;
    if (d > daysinmonth(y, m))
        return -1;
    *res = date_to_epoch(y, m, d);
    return 0;
}

/* parse "HH:MM" */
static int parse_hhmm(const char *s, int *h, int *m)
{
    const char *p = s;
    int n1 = 0, n2 = 0;
    if (!isdigit((unsigned char)*p))
        return -1;
    while (isdigit((unsigned char)*p)) { p++; n1++; }
    if (*p != ':')
        return -1;
    p++;
    if (!isdigit((unsigned char)*p))
        return -1;
    while (isdigit((unsigned char)*p)) { p++; n2++; }
    if (*p != '\0' || n1 > 2 || n2 > 2)
        return -1;
    *h = atoi(s);
    *m = atoi(strchr(s, ':') + 1);
    return 0;
}

/* ------------------------------------------------------------------ */
/* recurrence parsing: tokens inside "{...}"                           */
/* ------------------------------------------------------------------ */
static void recur_add_int(int **arr, int *n, int v)
{
    *arr = realloc(*arr, (*n + 1) * sizeof(int));
    (*arr)[(*n)++] = v;
}

static void parse_recur(item_t *it, char *p, char **endp, int line)
{
    recur_t *r = calloc(1, sizeof(recur_t));
    char *q = p;
    int neg = 0;

    it->rpt = r;
    if (*q != '{') {
        io_error(ERR_IO_DATA, "%s:%d: syntax error in item repetition", path_name(), line);
        exit(1);
    }
    q++;
    /* frequency */
    if (!isdigit((unsigned char)*q)) {
        io_error(ERR_IO_DATA, "%s:%d: syntax error in item repetition", path_name(), line);
        exit(1);
    }
    r->freq = atoi(q);
    while (isdigit((unsigned char)*q))
        q++;
    if (*q != 'D' && *q != 'W' && *q != 'M' && *q != 'Y')
        recur_error(ERR_RECUR_CHAR, "unknown character");
    r->rtype = *q++;
    /* optional " -> date" */
    if (*q == ' ') {
        const char *save = q;
        q++;
        if (*q == '-' && q[1] == '>') {
            long d;
            q += 2;
            if (parse_data_date(q, &d) < 0)
                io_error(ERR_IO_DATA, "%s:%d: syntax error in until date", path_name(), line);
            r->until = d;
            while (isdigit((unsigned char)*q) || *q == '/')
                q++;
        } else {
            q = (char *)save;
        }
    }
    /* inside tokens */
    for (;;) {
        while (*q == ' ')
            q++;
        if (*q == '!')
            break;
        if (*q == '}')
            break;
        if (*q == '\0')
            break;
        if (*q == 'd') {
            char *s = q + 1, *e;
            long v;
            if (!isdigit((unsigned char)*s) && *s != '-')
                recur_error(ERR_RECUR_BYMDAY, "syntax error in bymonthday");
            v = strtol(s, &e, 10);
            if (e == s)
                recur_error(ERR_RECUR_BYMDAY, "syntax error in bymonthday");
            if ((r->rtype == REC_WEEKLY))
                io_error(ERR_IO_DATA, "%s:%d: BYMONTHDAY illegal with WEEKLY", path_name(), line);
            recur_add_int(&r->bymday, &r->nbymday, (int)v);
            q = e;
            continue;
        }
        if (*q == 'w') {
            char *s = q + 1, *e;
            long v;
            v = strtol(s, &e, 10);
            if (e == s || (*e != '\0' && *e != ' ' && *e != '}'))
                recur_error(ERR_RECUR_BYDAY, "illegal BYDAY value");
            if ((r->rtype == REC_DAILY || r->rtype == REC_WEEKLY)) {
                if (v < 0 || v > 6)
                    recur_error(ERR_RECUR_BYDAY, "illegal BYDAY value");
            } else {
                int wd = (int)(v % 7);
                if (wd < 0)
                    wd += 7;
                if (v / 7 > 53 || v / 7 < -53)
                    ;
            }
            recur_add_int(&r->byday, &r->nbyday, (int)v);
            q = e;
            continue;
        }
        if (*q == 'm') {
            char *s = q + 1, *e;
            long v;
            v = strtol(s, &e, 10);
            if (e == s || v < 1 || v > 12)
                recur_error(ERR_RECUR_BYMON, "illegal bymonth value");
            recur_add_int(&r->bymon, &r->nbymon, (int)v);
            q = e;
            continue;
        }
        io_error(ERR_IO_DATA, "%s:%d: missing end of recurrence", path_name(), line);
    }
    /* exceptions inside the braces */
    while (*q == ' ') {
        if (*q == ' ') {
            q++;
            continue;
        }
        break;
    }
    while (*q == '!') {
        long d;
        exc_t *e;
        q++;
        if (!isdigit((unsigned char)*q))
            recur_error(ERR_RECUR_EXC, "syntax error in item date");
        if (parse_data_date(q, &d) < 0)
            recur_error(ERR_RECUR_EXCD, "date error in item exception");
        e = calloc(1, sizeof(exc_t));
        e->day = d;
        e->next = r->exc;
        r->exc = e;
        while (isdigit((unsigned char)*q) || *q == '/')
            q++;
        while (*q == ' ')
            q++;
    }
    if (*q != '}')
        io_error(ERR_IO_DATA, "%s:%d: missing end of recurrence", path_name(), line);
    q++;
    *endp = q;
    (void)neg;
}
CEOF
echo "part1 ok"; wc -l /workspace/src/io.c"}

