/* does the start date of the item match all the BY* constraints? */
static int recur_by_ok(item_t *it, long day)
{
    recur_t *r = it->rpt;
    int y, m, d;
    epoch_to_date(day, &y, &m, &d);
    if (r->nbyday) {
        int wd = weekday_of(y, m, d);
        int i, ok = 0;
        for (i = 0; i < r->nbyday; i++) {
            int v = r->byday[i];
            if (r->rtype == REC_DAILY || r->rtype == REC_WEEKLY) {
                if (v == wd)
                    ok = 1;
            } else {
                int ord = v / 7;
                int w = v % 7;
                if (w < 0) { w += 7; }
                if (w != wd)
                    continue;
                if (ord == 0) {
                    ok = 1;
                } else if (r->rtype == REC_MONTHLY || r->nbymon) {
                    /* nth weekday of the month */
                    int n, cnt = 0;
                    if (ord > 0) {
                        for (n = 1; n <= daysinmonth(y, m); n++) {
                            if (weekday_of(y, m, n) == w) {
                                cnt++;
                                if (cnt == ord && n == d) { ok = 1; break; }
                                if (cnt >= ord) break;
                            }
                        }
                    } else {
                        int total = 0, target;
                        for (n = daysinmonth(y, m); n >= 1; n--)
                            if (weekday_of(y, m, n) == w)
                                total++;
                        target = total + ord + 1;
                        cnt = 0;
                        for (n = 1; n <= daysinmonth(y, m); n++) {
                            if (weekday_of(y, m, n) == w) {
                                cnt++;
                                if (cnt == target && n == d) { ok = 1; break; }
                                if (cnt > target) break;
                            }
                        }
                    }
