    int y, m, d;
    epoch_to_date(day, &y, &m, &d);
    if (r->nbyday) {
        int wd = weekday_of(y, m, d);
        int i, ok = 0;
        for (i = 0; i < r->nbyday; i++) {
            int v = r->byday[i];
            if (r->rtype == REC_DAILY || r->rtype == REC_WEEKLY) {
                if (v == wd)
                    ok = 1;
            } else {
                int ord = v / 7;
                int w = v % 7;
                if (w < 0) { w += 7; }
                if (w != wd)
                    continue;
                if (ord == 0) {
                    ok = 1;
                } else if (r->rtype == REC_MONTHLY || r->nbymon) {
                    /* nth weekday of the month */
                    int n, cnt = 0;
                    if (ord > 0) {
                        for (n = 1; n <= daysinmonth(y, m); n++) {
                            if (weekday_of(y, m, n) == w) {
                                cnt++;
                                if (cnt == ord && n == d) { ok = 1; break; }
                                if (cnt >= ord) break;
                            }
                        }
                    } else {
                        int total = 0, target;
                        for (n = daysinmonth(y, m); n >= 1; n--)
                            if (weekday_of(y, m, n) == w)
                                total++;
                        target = total + ord + 1;
                        cnt = 0;
                        for (n = 1; n <= daysinmonth(y, m); n++) {
                            if (weekday_of(y, m, n) == w) {
                                cnt++;
                                if (cnt == target && n == d) { ok = 1; break; }
                                if (cnt > target) break;
                            }
                        }
                    }
                } else {
                    /* nth weekday of the year */
                    int n, cnt = 0, dn;
                    if (ord > 0) {
                        for (n = 1; n <= 366 && (dn = day_of_epoch(y,1,1) + n - 1, 1); n++) {
                            int yy, mm, dd;
                            day_to_date(dn, &yy, &mm, &dd);
                            if (yy != y) break;
                            if (weekday_of(yy, mm, dd) == w) {
                                cnt++;
                                if (cnt == ord && dd == d && mm == m) { ok = 1; break; }
                                if (cnt > ord) break;
                            }
                        }
                    }
                }
            }
            if (ok)
                break;
        }
        if (!ok)
            return 0;
    }
    if (r->nbymday) {
        int i, ok = 0;
        for (i = 0; i < r->nbymday; i++) {
            int v = r->bymday[i];
            if (v > 0 && v == d)
                ok = 1;
            else if (v < 0 && d == daysinmonth(y, m) + v + 1)
                ok = 1;
        }
        if (!ok)
            return 0;
    }
    if (r->nbymon) {
        int i, ok = 0;
        for (i = 0; i < r->nbymon; i++)
            if (r->bymon[i] == m)
                ok = 1;
        if (!ok)
            return 0;
    }
    return 1;
}

int recur_start_ok(item_t *it)
{
    if (!it->rpt)
        return 1;
    return recur_by_ok(it, it->start);
}
