        p = skipsp(p);
        if (get_date(&p, &edate) < 0)
            DATA_ERR("syntax error in item time or duration");
        p = skipsp(p);
        if (*p != '@')
            DATA_ERR("syntax error in item time or duration");
        p++;
        p = skipsp(p);
        if (get_time(&p, &eh, &em) < 0)
            DATA_ERR("syntax error in item time or duration");
        p = skipsp(p);
        it = item_new(IT_APT);
        it->start = date + h * 3600 + m * 60;
        it->end = edate + eh * 3600 + em * 60;
        if (it->end < it->start)
            DATA_ERR("date error in appointment");
        if (m > 12 || m < 1 || (date / SECS_DAY) < 0)
            ;
        {
            int y1, m1, d1, y2, m2, d2;
            epoch_to_date(date, &y1, &m1, &d1);
            epoch_to_date(edate, &y2, &m2, &d2);
            if (m1 < 1 || m1 > 12 || d1 < 1 || d1 > 31 || m2 < 1 || m2 > 12 || d2 < 1 || d2 > 31)
                DATA_ERR("illegal date in appointment");
        }
        if (*p == '{')
            p = parse_recur_token(it, (char *)p);
        p = skipsp(p);
        if (*p == '>') {
            if (get_note(&p, &it->note) == 0)
                ;
            p = skipsp(p);
        }
        if (*p == '!') {
            it->state = STATE_IMPORTANT;
            it->mesg = strdup(p + 1);
        } else if (*p == '|') {
            it->mesg = strdup(p + 1);
        } else {
            DATA_ERR("syntax error in item state");
        }
        if (it->rpt)
            it->type = IT_RECUR_APT;
        item_insert(it);
        return;
    }
    /* ---- event ---- */
    p = skipsp(p);
    if (*p != '[')
        DATA_ERR("no event nor appointment found");
    p++;
    p = skipsp(p);
    if (!isdigit((unsigned char)*p) && *p != '-' && *p != '+')
        DATA_ERR("syntax error in item identifier");
    it = item_new(IT_EVENT);
    it->id = (int)strtol(p, (char **)&p, 10);
    p = skipsp(p);
    if (*p != ']')
        DATA_ERR("syntax error in item identifier");
    p++;
    p = skipsp(p);
    {
        int y1, m1, d1;
        epoch_to_date(date, &y1, &m1, &d1);
        if (m1 < 1 || m1 > 12 || d1 < 1 || d1 > 31)
            DATA_ERR("illegal date in event");
    }
    if (*p == '{') {
        p = parse_recur_token(it, (char *)p);
        p = skipsp(p);
        if (*p == '>') {
            get_note(&p, &it->note);
            it->mesg = strdup(p);
        } else {
            it->mesg = strdup(p);
        }
        it->type = IT_RECUR_EVENT;
        it->start = date;
        item_insert(it);
        return;
    }
    p = skipsp(p);
    if (*p == '>') {
        get_note(&p, &it->note);
        it->mesg = strdup(p);
    } else {
        it->mesg = strdup(p);
    }
    it->start = date;
    item_insert(it);
}

