#define _GNU_SOURCE
#include "calcurse.h"
#include "query.h"
#include "io.h"
#include "dates.h"
#include "args.h"
#include <ctype.h>
#include <math.h>

int grep_mode = 0;
long query_now;

/* ------------------------------------------------------------------ */
/* sha1                                                                */
/* ------------------------------------------------------------------ */
typedef unsigned int u32;
typedef struct {
    u32 h[5];
    u64 len;
    unsigned char buf[64];
    size_t blen;
} sha1_ctx;

static u32 rol(u32 x, int n) { return (x << n) | (x >> (32 - n)); }

static void sha1_block(sha1_ctx *c, const unsigned char *p)
{
    u32 w[80], a, b, cc, d, e, f, k, t;
    int i;
    for (i = 0; i < 16; i++)
        w[i] = ((u32)p[i * 4] << 24) | ((u32)p[i * 4 + 1] << 16) |
               ((u32)p[i * 4 + 2] << 8) | (u32)p[i * 4 + 3];
    for (i = 16; i < 80; i++)
        w[i] = rol(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    a = c->h[0]; b = c->h[1]; cc = c->h[2]; d = c->h[3]; e = c->h[4];
    for (i = 0; i < 80; i++) {
        if (i < 20)      { f = (b & cc) | ((~b) & d);      k = 0x5A827999; }
        else if (i < 40) { f = b ^ cc ^ d;                 k = 0x6ED9EBA1; }
        else if (i < 60) { f = (b & cc) | (b & d) | (cc & d); k = 0x8F1CDCDC; }
        else             { f = b ^ cc ^ d;                 k = 0xCA62C1D6; }
        t = rol(a, 5) + f + e + k + w[i];
        e = d; d = cc; cc = rol(b, 30); b = a; a = t;
    }
    c->h[0] += a; c->h[1] += b; c->h[2] += cc; c->h[3] += d; c->h[4] += e;
}

static void sha1_init(sha1_ctx *c)
{
    c->h[0] = 0x67452301; c->h[1] = 0xEFCDAB89; c->h[2] = 0x98BADCFE;
    c->h[3] = 0x10325476; c->h[4] = 0xC3D2E1F0;
    c->len = 0; c->blen = 0;
}

static void sha1_update(sha1_ctx *c, const void *data, size_t n)
{
    const unsigned char *p = data;
    c->len += n;
    while (n) {
        size_t k = 64 - c->blen;
        if (k > n)
            k = n;
        memcpy(c->buf + c->blen, p, k);
        c->blen += k; p += k; n -= k;
        if (c->blen == 64) {
            sha1_block(c, c->buf);
            c->blen = 0;
        }
    }
}

static void sha1_final(sha1_ctx *c, unsigned char out[20])
{
    u64 bits = c->len * 8;
    unsigned char pad = 0x80;
    int i;
    sha1_update(c, &pad, 1);
    pad = 0;
    while (c->blen != 56)
        sha1_update(c, &pad, 1);
    for (i = 7; i >= 0; i--) {
        unsigned char b = (unsigned char)((bits >> (i * 8)) & 0xff);
        sha1_update(c, &b, 1);
    }
    for (i = 0; i < 5; i++) {
        out[i * 4]     = (unsigned char)(c->h[i] >> 24);
        out[i * 4 + 1] = (unsigned char)(c->h[i] >> 16);
        out[i * 4 + 2] = (unsigned char)(c->h[i] >> 8);
        out[i * 4 + 3] = (unsigned char)(c->h[i]);
    }
}

int hash_of(item_t *it, char *out)
{
    sha1_ctx c;
    unsigned char dig[20];
    char *raw = item_raw(it);
    int i;
    sha1_init(&c);
    sha1_update(&c, raw, strlen(raw));
    sha1_final(&c, dig);
    for (i = 0; i < 20; i++)
        sprintf(out + i * 2, "%02x", dig[i]);
    out[40] = '\0';
    return 0;
}
CEOF
echo ok"}

