static void print_day(long day, int *first)
{
    long ds = day * SECS_DAY;
    long de = ds + SECS_DAY - 1;
    item_t *p;
    int cnt = 0;
    char dbuf[64];

    /* count items */
    for (p = recur_events; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ >= 0 && occ <= de && filter_item(p))
            cnt++;
    }
    for (p = events; p; p = p->next)
        if (p->start >= ds && p->start <= de && filter_item(p))
            cnt++;
    for (p = recur_apoints; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ >= 0 && occ <= de && occ + (p->end - p->start) >= ds && filter_item(p))
            cnt++;
    }
    for (p = apoints; p; p = p->next)
        if (p->end >= ds && p->start <= de && filter_item(p))
            cnt++;
    if (cnt == 0)
        return;
    if (!*first)
        putchar('\n');
