        if (occ >= 0 && occ <= de && filter_item(p))
            cnt++;
    }
    for (p = events; p; p = p->next)
        if (p->start >= ds && p->start <= de && filter_item(p))
            cnt++;
    for (p = recur_apoints; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ >= 0 && occ <= de && occ + (p->end - p->start) >= ds && filter_item(p))
            cnt++;
    }
    for (p = apoints; p; p = p->next)
        if (p->end >= ds && p->start <= de && filter_item(p))
            cnt++;
    if (cnt == 0)
        return;
    if (!*first)
        putchar('\n');
    date_str(dbuf, sizeof(dbuf), ds);
    printf("%s:\n", dbuf);
    *first = 0;
    for (p = recur_events; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ < 0 || occ > de)
            continue;
        if (!filter_item(p))
            continue;
        fmt_render(p, occ, occ, day, fmts.recur_event, stdout);
        if (args.limit_set && --args.limit <= 0)
            return;
    }
    for (p = events; p; p = p->next) {
        if (p->start < ds || p->start > de)
            continue;
        if (!filter_item(p))
            continue;
        fmt_render(p, p->start, p->start, day, fmts.event, stdout);
        if (args.limit_set && --args.limit <= 0)
            return;
    }
    for (;;) {
        item_t *best = NULL;
        long bt = 0;
        for (p = recur_apoints; p; p = p->next) {
            long occ = recur_next(p, ds);
            if (occ < 0 || occ > de || occ + (p->end - p->start) < ds)
                continue;
            if (!filter_item(p))
                continue;
            if (!best || occ < bt) {
                best = p; bt = occ;
            }
        }
        for (p = apoints; p; p = p->next) {
            if (p->end < ds || p->start > de)
                continue;
            if (!filter_item(p))
                continue;
            if (!best || p->start < bt) {
                best = p; bt = p->start;
            }
        }
        if (!best)
            break;
        if (best->type == IT_RECUR_APT) {
            long occ = recur_next(best, ds);
            fmt_render(best, occ, occ + (best->end - best->start), day, fmts.recur_apt, stdout);
        } else
            fmt_render(best, best->start, best->end, day, fmts.apt, stdout);
        if (args.limit_set && --args.limit <= 0)
            return;
        best->state |= 0x1000;   /* mark printed */
    }
    /* clear marks */
    for (p = recur_apoints; p; p = p->next)
        p->state &= ~0x1000;
    for (p = apoints; p; p = p->next)
        p->state &= ~0x1000;
}

void query_run(void)
{
    long from, to, day;
    int first = 1;
    item_t *p;

    query_now = time(NULL);
    if (filter.mask & FILTER_TODO)
        print_todo_section(&first);
    if (filter.mask & (FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT)) {
        day_range(&from, &to);
        for (day = from; day <= to; day += SECS_DAY)
            print_day(day / SECS_DAY, &first);
    }
    (void)p;
}
