    for (p = recur_events; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->start, p->start / SECS_DAY, fmts.recur_event, stdout);
    }
    for (p = recur_apoints; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->end, p->start / SECS_DAY, fmts.recur_apt, stdout);
    }
    for (p = apoints; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->end, p->start / SECS_DAY, fmts.apt, stdout);
    }
    for (p = events; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->start, p->start / SECS_DAY, fmts.event, stdout);
    }
}

/* ------------------------------------------------------------------ */
/* -P : purge                                                          */
/* ------------------------------------------------------------------ */
void purge_run(void)
{
    item_t *p, *n;
    item_t *keep_head[5], *keep_tail[5];
    int i;
    for (i = 0; i < 5; i++) {
        keep_head[i] = keep_tail[i] = NULL;
    }
    for (i = 0; i < 5; i++) {
        item_t **src;
        switch (i) {
        case 0: src = &todolist; break;
        case 1: src = &recur_events; break;
        case 2: src = &recur_apoints; break;
        case 3: src = &apoints; break;
        default: src = &events; break;
        }
        for (p = *src; p; p = n) {
            n = p->next;
            if (!filter_item(p)) {
                if (keep_tail[i])
                    keep_tail[i]->next = p;
                else
                    keep_head[i] = p;
                keep_tail[i] = p;
                p->next = NULL;
            } else {
                item_free(p);
            }
        }
        *src = NULL;
    }
    todolist = keep_head[0];
    recur_events = keep_head[1];
    recur_apoints = keep_head[2];
    apoints = keep_head[3];
    events = keep_head[4];
    for (p = keep_head[0]; p; p = p->next)
        keep_tail[0] = p;
    for (p = keep_head[1]; p; p = p->next)
        keep_tail[1] = p;
    for (p = keep_head[2]; p; p = p->next)
        keep_tail[2] = p;
    for (p = keep_head[3]; p; p = p->next)
        keep_tail[3] = p;
    for (p = keep_head[4]; p; p = p->next)
        keep_tail[4] = p;
    /* restore list linkage */
    (void)keep_tail;
    io_save_data();
}

/* ------------------------------------------------------------------ */
/* -n : next appointment                                               */
/* ------------------------------------------------------------------ */
void next_run(void)
{
    item_t *p;
    long best = -1;
    char *bestmsg = NULL;
    long delta;

    query_now = time(NULL);
    for (p = apoints; p; p = p->next) {
        if (p->start > query_now && p->start <= query_now + 24 * 3600) {
            if (best < 0 || p->start < best) {
                best = p->start;
                bestmsg = p->mesg;
            }
        }
    }
    for (p = recur_apoints; p; p = p->next) {
        long occ = recur_next(p, query_now + 1);
        if (occ > 0 && occ > query_now && occ <= query_now + 24 * 3600) {
            if (best < 0 || occ < best) {
                best = occ;
                bestmsg = p->mesg;
            }
        }
    }
    if (best < 0)
        return;
    delta = best - query_now;
    printf("next appointment:\n");
    printf("   [%02ld:%02ld] %s\n", delta / 3600, (delta % 3600) / 60,
           bestmsg ? bestmsg : "");
}
