void args_error(int line, const char *fmt, ...)
{
    va_list ap;
    if (args.early_set)
        return;                     /* errors are suppressed after -h/-v */
    fprintf(stderr, "args.c: %d: ", line);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    exit(1);
}

void args_usage_error(void)
