#define _GNU_SOURCE
#include "calcurse.h"
#include "args.h"
#include <ctype.h>

conf_t conf;

static int boolval(const char *s, int def)
{
    if (!s || !*s)
        return def;
    if (!strcasecmp(s, "yes") || !strcmp(s, "1") || !strcasecmp(s, "true"))
        return 1;
    if (!strcasecmp(s, "no") || !strcmp(s, "0") || !strcasecmp(s, "false"))
        return 0;
    return def;
}

void conf_load(void)
{
    char path[1024];
    FILE *fp;
    char line[MAX_CONF_LINE];
    char *p, *v;

    memset(&conf, 0, sizeof(conf));
    conf.compactpanels = 0;
    conf.defaultpanel = 0;
    conf.autosave = 1;
    conf.autogc = 0;
    conf.periodicsave = 0;
    conf.confirmquit = 1;
    conf.confirmdelete = 1;
    conf.systemdialogs = 1;
    conf.progressbar = 1;
    conf.calendarview = 0;
    conf.firstdayofweek = 1;              /* monday */
    strcpy(conf.outputdate, "%D");
    conf.inputdate = 1;
    conf.layout = 0;
    conf.sidebarwidth = 0;
    conf.notifybar = 1;
    strcpy(conf.notifydate, "%a %F");
    strcpy(conf.notifytime, "%T");
    conf.warning = 300;
    strcpy(conf.command, "printf '\\a'");
    conf.notifyall = 0;
    conf.daemon_enable = 0;
    conf.daemon_log = 0;

    if (args.output_datefmt_set)
        return;
    snprintf(path, sizeof(path), "%s/conf", confdir);
    if ((fp = fopen(path, "r")) == NULL)
        return;
    while (fgets(line, sizeof(line), fp)) {
        size_t l = strlen(line);
        while (l && (line[l - 1] == '\n' || line[l - 1] == '\r'))
            line[--l] = '\0';
        p = line;
        while (*p == ' ' || *p == '\t')
            p++;
        if (*p == '#' || *p == '\0')
            continue;
        v = strchr(p, '=');
        if (!v)
            continue;
        *v++ = '\0';
        while (strlen(p) && (p[strlen(p) - 1] == ' ' || p[strlen(p) - 1] == '\t'))
            p[strlen(p) - 1] = '\0';
        while (*v == ' ' || *v == '\t')
            v++;
        if (!strcmp(p, "appearance.compactpanels"))
            conf.compactpanels = boolval(v, 0);
        else if (!strcmp(p, "appearance.defaultpanel")) {
            if (!strcasecmp(v, "appts") || !strcasecmp(v, "appointments"))
                conf.defaultpanel = 1;
            else if (!strcasecmp(v, "todo"))
                conf.defaultpanel = 2;
            else
                conf.defaultpanel = 0;
        } else if (!strcmp(p, "general.autosave"))
            conf.autosave = boolval(v, 1);
        else if (!strcmp(p, "general.autogc"))
            conf.autogc = boolval(v, 0);
        else if (!strcmp(p, "general.periodicsave"))
            conf.periodicsave = atoi(v);
        else if (!strcmp(p, "general.confirmquit"))
            conf.confirmquit = boolval(v, 1);
        else if (!strcmp(p, "general.confirmdelete"))
            conf.confirmdelete = boolval(v, 1);
        else if (!strcmp(p, "general.systemdialogs"))
            conf.systemdialogs = boolval(v, 1);
        else if (!strcmp(p, "general.progressbar"))
            conf.progressbar = boolval(v, 1);
        else if (!strcmp(p, "appearance.calendarview"))
            conf.calendarview = atoi(v);
        else if (!strcmp(p, "general.firstdayofweek"))
            conf.firstdayofweek = (!strcasecmp(v, "sunday")) ? 0 : 1;
        else if (!strcmp(p, "format.outputdate"))
            strncpy(conf.outputdate, v, sizeof(conf.outputdate) - 1);
        else if (!strcmp(p, "format.inputdate"))
            conf.inputdate = atoi(v);
        else if (!strcmp(p, "appearance.layout"))
            conf.layout = atoi(v);
        else if (!strcmp(p, "appearance.sidebarwidth"))
            conf.sidebarwidth = atoi(v);
        else if (!strcmp(p, "appearance.notifybar"))
            conf.notifybar = boolval(v, 1);
        else if (!strcmp(p, "format.notifydate"))
            strncpy(conf.notifydate, v, sizeof(conf.notifydate) - 1);
        else if (!strcmp(p, "format.notifytime"))
            strncpy(conf.notifytime, v, sizeof(conf.notifytime) - 1);
        else if (!strcmp(p, "notification.warning"))
            conf.warning = atoi(v);
        else if (!strcmp(p, "notification.command"))
            strncpy(conf.command, v, sizeof(conf.command) - 1);
        else if (!strcmp(p, "notification.notifyall"))
            conf.notifyall = (!strcasecmp(v, "all")) ? 1 : 0;
        else if (!strcmp(p, "daemon.enable"))
            conf.daemon_enable = boolval(v, 0);
        else if (!strcmp(p, "daemon.log"))
            conf.daemon_log = boolval(v, 0);
        else if (!strcmp(p, "todo.systemevents") || !strcmp(p, "todo.systemevents"))
            ;
        else
            printf("unknown user option: \"%s\" (ignored)\n", p);
    }
    fclose(fp);
}

void keys_load(void)
{
    char path[1024];
    FILE *fp;
    snprintf(path, sizeof(path), "%s/keys", confdir);
    if ((fp = fopen(path, "r")) == NULL)
        return;
    fclose(fp);
}

void keys_save(void)
{
    char path[1024];
    static const char *keys[] = {
        "generic-cancel",       "ESC",
        "generic-select",       "SPC",
        "generic-credits",      "@",
        "generic-help",         "?",
        "generic-quit",         "q Q",
        "generic-save",         "s S ^S",
        "generic-reload",       "R",
        "generic-copy",         "c",
