        "generic-change-view",  "TAB",
        "generic-prev-view",    "KEY_BTAB",
        "generic-import",       "i I",
        "generic-export",       "x X",
        "generic-goto",         "g G",
        "generic-other-cmd",    "o O",
        "generic-config-menu",  "C",
        "generic-redraw",       "^R",
        "generic-add-appt",     "^A",
        "generic-add-todo",     "^T",
        "generic-prev-day",     "T ^H",
        "generic-next-day",     "t ^L",
        "generic-prev-week",    "W ^K",
        "generic-next-week",    "w",
        "generic-prev-month",   "M",
        "generic-next-month",   "m",
        "generic-prev-year",    "Y",
        "generic-next-year",    "y",
        "generic-scroll-down",  "^N",
        "generic-scroll-up",    "^P",
        "generic-goto-today",   "^G",
        "generic-command",      ":",
        "move-right",           "l L RGT",
        "move-left",            "h H LFT",
        "move-down",            "j J DWN",
        "move-up",              "k K UP",
        "start-of-week",        "0",
        "end-of-week",          "$",
        "add-item",             "a A",
        "del-item",             "d D",
        "edit-item",            "e E",
        "view-item",            "v V RET",
        "pipe-item",            "|",
        "flag-item",            "!",
        "repeat",               "r",
        "edit-note",            "n N",
        "view-note",            ">",
        "raise-priority",       "+",
        "lower-priority",       "-",
        NULL, NULL
    };
    int i;
    FILE *fp;
    snprintf(path, sizeof(path), "%s/keys", confdir);
    if ((fp = fopen(path, "w")) == NULL)
        return;
    fputs("#\n# Calcurse keys configuration file\n#\n", fp);
    fputs("# In this file the keybindings used by Calcurse are defined.\n", fp);
    fputs("# It is generated automatically by Calcurse and is maintained\n", fp);
    fputs("# via the key configuration menu of the interactive user\n", fp);
    fputs("# interface. It should not be edited directly.\n\n", fp);
    for (i = 0; keys[i]; i += 2)
        fprintf(fp, "%s  %s\n", keys[i], keys[i + 1]);
    fclose(fp);
}
CEOF
echo ok"}

