{
    return regcomp_real(re, pat, flags);
}

int regexec_wrap(regex_t *re, const char *s, size_t n, regmatch_t *m, int eflags)
{
    return regexec_real(re, s, n, m, eflags);
}

static void mkdirs(const char *path)
{
    char tmp[1024];
    char *p;
    size_t l;
    snprintf(tmp, sizeof(tmp), "%s", path);
    l = strlen(tmp);
    while (l > 1 && tmp[l - 1] == '/')
        tmp[--l] = '\0';
    for (p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, 0700);
            *p = '/';
        }
    }
    mkdir(tmp, 0700);
}

static void touch_file(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (fp)
        fclose(fp);
}

void io_init(void)
{
    char buf[1024];
    const char *home = getenv("HOME");
    const char *xdg;
    struct stat st;

    if (!home)
        home = "";
    snprintf(buf, sizeof(buf), "%s/.calcurse", home);
    if (stat(buf, &st) == 0 && S_ISDIR(st.st_mode)) {
        snprintf(datadirbuf, sizeof(datadirbuf), "%s", buf);
        snprintf(confdirbuf, sizeof(confdirbuf), "%s", buf);
    } else {
        xdg = getenv("XDG_DATA_HOME");
        if (xdg && *xdg)
            snprintf(datadirbuf, sizeof(datadirbuf), "%s/calcurse", xdg);
        else
            snprintf(datadirbuf, sizeof(datadirbuf), "%s/.local/share/calcurse", home);
        xdg = getenv("XDG_CONFIG_HOME");
        if (xdg && *xdg)
            snprintf(confdirbuf, sizeof(confdirbuf), "%s/calcurse", xdg);
        else
            snprintf(confdirbuf, sizeof(confdirbuf), "%s/.config/calcurse", home);
    }
    if (args.datadir_opt) {
        snprintf(datadirbuf, sizeof(datadirbuf), "%s", datadir_arg);
        if (!args.confdir_opt)
            snprintf(confdirbuf, sizeof(confdirbuf), "%s", datadir_arg);
    }
    if (args.confdir_opt)
        snprintf(confdirbuf, sizeof(confdirbuf), "%s", confdir_arg);
    datadir = datadirbuf;
    confdir = confdirbuf;
    mkdirs(datadir);
    mkdirs(confdir);
    snprintf(confpath, sizeof(confpath), "%s/conf", confdir);
    snprintf(keyspath, sizeof(keyspath), "%s/keys", confdir);
    if (access(confpath, F_OK) != 0)
        touch_file(confpath);
    snprintf(buf, sizeof(buf), "%s/hooks", confdir);
    mkdir(buf, 0700);
    snprintf(calendarbuf, sizeof(calendarbuf), "%s/apts", datadir);
    if (calendarfile == NULL)
        calendarfile = calendarbuf;
    snprintf(buf, sizeof(buf), "%s/todo", datadir);
    todofile_name = strdup(buf);
}

void io_load_calendar(void) { apts_load(calendarfile); }
void io_load_todo(void) { todo_load(todofile_name); }

void io_save_data(void)
{
    if (readonly_flag)
        return;
    apts_save(calendarfile);
    todo_save(todofile_name);
    {
        char buf[1024];
        snprintf(buf, sizeof(buf), "%s/notes", datadir);
        mkdir(buf, 0700);
    }
}

int io_check_lock(void)
{
    char path[1024];
    snprintf(path, sizeof(path), "%s/.calcurse.pid", datadir);
    return access(path, F_OK) == 0;
}

void io_write_pid(void)
{
    char path[1024];
    FILE *fp;
    snprintf(path, sizeof(path), "%s/.calcurse.pid", datadir);
    if ((fp = fopen(path, "w")) == NULL)
        return;
    fprintf(fp, "%d\n", (int)getpid());
    fclose(fp);
}

void io_remove_pid(void)
{
    char path[1024];
    snprintf(path, sizeof(path), "%s/.calcurse.pid", datadir);
    unlink(path);
}

static void load_all(void)
{
    conf_load();
    keys_load();
    apts_load(calendarfile);
    todo_load(todofile_name);
}

int main(int argc, char **argv)
{
    args_parse(argc, argv);
    if (args.early_set) {
        if (args.early_op == OP_HELP) {
            args_print_help();
            return 0;
        }
        args_print_version();
        return 0;
    }
    args_check();
    io_init();
    /* check that an alternative calendar file exists */
    if (calendarfile && strcmp(calendarfile, calendarbuf) != 0 &&
        access(calendarfile, F_OK) != 0)
        io_error(ERR_IO_CALENDAR, "%s does not exist", calendarfile);

    switch (args.op) {
    case OP_STATUS:
        status_run();
        return 0;
    case OP_GC:
        load_all();
        gc_run();
        return 0;
    case OP_IMPORT:
        load_all();
        import_run();
        return 0;
    case OP_EXPORT:
        load_all();
        export_run();
        return 0;
    case OP_GREP:
    case OP_PURGE:
        load_all();
        if (args.op == OP_GREP)
            grep_run();
        else
            purge_run();
        return 0;
    case OP_QUERY:
    case OP_APPOINT:
    case OP_DAY:
    case OP_RANGE:
    case OP_STARTDAY:
    case OP_TODO:
        load_all();
        query_run();
        return 0;
    case OP_NEXT:
        load_all();
        next_run();
        return 0;
    case OP_DAEMON:
        daemon_run();
        return 0;
    default:
        break;
    }
    ui_run();
    return 0;
}
