                    imp_skip(&im, "exception date, but no recurrence rule.");
                } else {
                    if (im.exdate_set)
                        strcat(im.exdate, ",");
                    strncat(im.exdate, val, sizeof(im.exdate) - strlen(im.exdate) - 1);
                    im.exdate_set = 1;
                }
            } else if (!strcmp(name, "SUMMARY")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (im.summary)
                    free(im.summary);
                im.summary = s;
            } else if (!strcmp(name, "DESCRIPTION")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (im.desc)
                    free(im.desc);
                im.desc = s;
            } else if (!strcmp(name, "COMMENT")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (!im.desc) {
