                if (im.loc_set)
                    imp_skip(&im, "only one location allowed.");
                else
                    im.loc_set = 1;
            } else if (!strcmp(name, "UID")) {
                strncpy(im.uid, val, sizeof(im.uid) - 1);
            }
            free(name);
        }
    }
    fclose(fp);
    if (im.log)
        fclose(im.log);
    if (im.nskipped > 0)
        logused = 1;
    /* save */
    io_save_data();
