        else break;
    }
    return sign * res;
}

static void split_params(char *s, char **name, char **val, int *isdate)
{
    char *p = s, *q;
    *isdate = 0;
    *name = s;
    q = strchr(s, ':');
    if (!q) { *val = NULL; return; }
    *q = '\0';
    *val = q + 1;
    /* look for VALUE=DATE in the parameters */
    {
        char *r = strchr(s, ';');
        char tmp[256];
        if (r) {
            *r = '\0';
            snprintf(tmp, sizeof(tmp), "%s", r + 1);
            *r = ';';
            if (strstr(tmp, "VALUE=DATE") || strstr(tmp, "VALUE=DATE-TIME"))
                if (strstr(tmp, "VALUE=DATE"))
                    *isdate = 1;
        }
    }
    (void)p;
}

/* ------------------------------------------------------------------ */
/* import                                                              */
/* ------------------------------------------------------------------ */
struct imp {
    int line;
    FILE *log;
    int nskipped;
    int napps, nevents, ntodos;
    int dump;
    char *desc;        /* DESCRIPTION or COMMENT */
    char *summary;
    long dtstart; int dtstart_isdate, dtstart_set;
    long dtend; int dtend_set;
    long dur; int dur_set;
    char rrule[1024]; int rrule_set;
    char exdate[4096]; int exdate_set;
    int priority; int prio_set;
    int isvtodo;
    int alarm;
    int item_line;
    char uid[256];
};

static void imp_reset(struct imp *im)
{
    free(im->desc); im->desc = NULL;
    free(im->summary); im->summary = NULL;
    im->dtstart_set = 0; im->dtstart = 0; im->dtstart_isdate = 0;
    im->dtend_set = 0; im->dtend = 0;
    im->dur_set = 0; im->dur = 0;
    im->rrule_set = 0; im->rrule[0] = '\0';
    im->exdate_set = 0; im->exdate[0] = '\0';
    im->priority = 0; im->prio_set = 0;
    im->alarm = 0;
    im->uid[0] = '\0';
}

static void imp_skip(struct imp *im, const char *why)
{
    if (im->log) {
        fprintf(im->log, "%s [%d]: %s\n", im->isvtodo ? "VTODO" : "VEVENT",
                im->item_line, why);
    }
    imp_reset(im);
    im->nskipped++;
}

/* add the item described by im to the internal lists */
static void imp_commit(struct imp *im)
{
    item_t *it;
    long start = im->dtstart, end;
    int dur = im->dur;

    if (im->isvtodo) {
        it = item_new(IT_TODO);
        it->prio = im->prio_set ? im->priority : 0;
        if (im->priority > 9)
            it->prio = 0;
        it->mesg = strdup(im->summary ? im->summary : "");
        item_insert(it);
        im->ntodos++;
    } else if (im->dtstart_isdate) {
        /* all day item */
        if (im->rrule_set) {
            it = item_new(IT_RECUR_EVENT);
            it->start = start;
            it->mesg = strdup(im->summary ? im->summary : "");
            /* parse the rrule into a recur_t */
            ical_rrule_to_recur(it, im->rrule, start);
            item_insert(it);
        } else {
            it = item_new(IT_EVENT);
            it->start = start;
            it->mesg = strdup(im->summary ? im->summary : "");
            item_insert(it);
        }
        im->nevents++;
    } else {
        end = im->dtend_set ? im->dtend : start + dur;
        if (im->rrule_set) {
            it = item_new(IT_RECUR_APT);
            it->start = start;
            it->end = end;
            it->mesg = strdup(im->summary ? im->summary : "");
            ical_rrule_to_recur(it, im->rrule, start);
            item_insert(it);
        } else {
            it = item_new(IT_APT);
            it->start = start;
            it->end = end;
            it->mesg = strdup(im->summary ? im->summary : "");
            item_insert(it);
        }
        im->napps++;
    }
    if (im->desc && im->desc[0]) {
        char *note = malloc(strlen(im->desc) + 8);
        sprintf(note, "-- \n%s\n", im->desc);
        /* the note file name is the sha1 of its content */
        {
            sha1_ctx c;
            unsigned char dig[20];
            char name[41];
            char path[1200];
            FILE *fp;
            int i;
            sha1_init(&c);
            sha1_update(&c, note, strlen(note));
            sha1_final(&c, dig);
            for (i = 0; i < 20; i++)
                sprintf(name + i * 2, "%02x", dig[i]);
            name[40] = '\0';
            snprintf(path, sizeof(path), "%s/notes/%s", datadir, name);
            if ((fp = fopen(path, "w")) != NULL) {
                fputs(note, fp);
                fclose(fp);
            }
            if (it->note)
                free(it->note);
            it->note = strdup(name);
        }
        free(note);
    }
    if (im->alarm)
        it->state |= STATE_IMPORTANT;
    if (im->dump) {
        char *raw = item_raw(it);
        printf("%s\n", raw);
    }
    imp_reset(im);
}

int ical_import(const char *file, int dump, int quiet)
{
    FILE *fp;
    struct imp im;
    char line[8192];
    int nl = 0;
    int header_ok = 0;
    char logpath[256];
    int logfd;
    int logused = 0;

    memset(&im, 0, sizeof(im));
    im.dump = dump;
    if ((fp = fopen(file, "r")) == NULL) {
        io_error(ERR_IO_INPUT, "FATAL ERROR: the input file cannot be accessed, Aborting...");
        return 1;
    }
    if (access(datadir, F_OK) != 0)
        mkdir(datadir, 0700);
    {
        char b[1024];
        snprintf(b, sizeof(b), "%s/notes", datadir);
        mkdir(b, 0700);
    }
    strcpy(logpath, "/tmp/calcurse_log.XXXXXX");
    logfd = mkstemp(logpath);
    im.log = logfd >= 0 ? fdopen(logfd, "w") : NULL;
    while (fgets(line, sizeof(line), fp)) {
        size_t l;
        nl++;
        l = strlen(line);
        while (l && (line[l - 1] == '\n' || line[l - 1] == '\r'))
            line[--l] = '\0';
        unfold(line, fp);
        if (!strncmp(line, "BEGIN:VCALENDAR", 15)) {
            header_ok = 1;
            continue;
        }
        if (!strncmp(line, "VERSION:", 8)) {
            if (strcmp(line + 8, "2.0") != 0 && !header_ok) {
                ;
            }
            continue;
        }
        if (!strncmp(line, "BEGIN:VEVENT", 12)) {
            im.isvtodo = 0;
            im.item_line = nl;
            continue;
        }
        if (!strncmp(line, "BEGIN:VTODO", 11)) {
            im.isvtodo = 1;
            im.item_line = nl;
            continue;
        }
        if (!strncmp(line, "BEGIN:VALARM", 12)) {
            im.alarm = 1;
            continue;
        }
        if (!strncmp(line, "END:VALARM", 10))
            continue;
        if (!strncmp(line, "END:VEVENT", 10) || !strncmp(line, "END:VTODO", 9)) {
            imp_commit(&im);
            continue;
        }
        if (!strncmp(line, "END:VCALENDAR", 13))
            continue;
        {
            char *name, *val;
            int isdate;
            split_params(line, &name, &val, &isdate);
            if (!val)
                continue;
            if (!strcmp(name, "DTSTART")) {
                long t = parse_ical_dt(val, &isdate);
                if (t < 0)
                    imp_skip(&im, "invalid or malformed event start time.");
                else {
                    im.dtstart = t;
                    im.dtstart_isdate = isdate;
                    im.dtstart_set = 1;
                }
            } else if (!strcmp(name, "DTEND")) {
                long t = parse_ical_dt(val, &isdate);
                if (t < 0)
                    imp_skip(&im, "invalid end time value type.");
                else {
                    im.dtend = t;
                    im.dtend_set = 1;
                    if (isdate)
                        im.dtend -= 1;
                }
            } else if (!strcmp(name, "DURATION")) {
                long d = parse_ical_dur(val);
                if (d < 0)
                    imp_skip(&im, "invalid duration.");
                else {
                    im.dur = d;
                    im.dur_set = 1;
                }
            } else if (!strcmp(name, "RRULE")) {
                strncpy(im.rrule, val, sizeof(im.rrule) - 1);
                im.rrule_set = 1;
            } else if (!strcmp(name, "EXDATE")) {
                if (!im.rrule_set) {
                    imp_skip(&im, "exception date, but no recurrence rule.");
                } else {
                    if (im.exdate_set)
                        strcat(im.exdate, ",");
                    strncat(im.exdate, val, sizeof(im.exdate) - strlen(im.exdate) - 1);
                    im.exdate_set = 1;
                }
            } else if (!strcmp(name, "SUMMARY")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (im.summary)
                    free(im.summary);
                im.summary = s;
            } else if (!strcmp(name, "DESCRIPTION")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (im.desc)
                    free(im.desc);
                im.desc = s;
            } else if (!strcmp(name, "COMMENT")) {
                char *s = strdup(val);
                ical_unescape(s);
                if (!im.desc) {
                    char *n = malloc(strlen(s) + 16);
                    sprintf(n, "\n%s\n", s);
                    im.desc = n;
                }
                free(s);
            } else if (!strcmp(name, "PRIORITY")) {
                if (im.isvtodo) {
                    int p = atoi(val);
                    if (p < 0 || p > 9)
                        imp_skip(&im, "item priority is invalid (must be between 0 and 9).");
                    else {
                        im.priority = p;
                        im.prio_set = 1;
                    }
                }
            } else if (!strcmp(name, "LOCATION")) {
                if (im.loc_set)
                    imp_skip(&im, "only one location allowed.");
                else
                    im.loc_set = 1;
            } else if (!strcmp(name, "UID")) {
                strncpy(im.uid, val, sizeof(im.uid) - 1);
            }
            free(name);
        }
    }
    fclose(fp);
    if (im.log)
        fclose(im.log);
    if (im.nskipped > 0)
        logused = 1;
    /* save */
    io_save_data();
    if (!quiet) {
        printf("Import process report: %04d lines read\n", nl);
        printf("%d apps / %d events / %d todos / %d skipped\n",
               im.napps, im.nevents, im.ntodos, im.nskipped);
    }
    if (im.nskipped > 0) {
        putchar('\n');
        puts("Some items could not be imported.");
        printf("See %s for details.\n", logpath);
        unlink(logpath);
        return 1;
    }
    if (logfd >= 0)
        unlink(logpath);
    return 0;
}
CEOF
echo ok"}

{"command": "cat > /workspace/src/ical.c <<'CEOF'
/*
 * iCalendar import/export and pcal export.
 */
#define _GNU_SOURCE
#include "calcurse.h"
#include "ical.h"
#include "io.h"
#include "query.h"
#include "dates.h"
#include <ctype.h>
#include <unistd.h>

static const char *wday_name[7] = { "SU", "MO", "TU", "WE", "TH", "FR", "SA" };

/* ------------------------------------------------------------------ */
/* low level helpers                                                   */
/* ------------------------------------------------------------------ */
static void ical_unescape(char *s)
{
    char *p = s, *q = s;
    while (*p) {
        if (*p == '\\' && p[1]) {
            p++;
            switch (*p) {
            case 'n': case 'N': *q++ = '\n'; break;
            case 't': case 'T': *q++ = '\t'; break;
            case ',': case ';': case '\\': *q++ = *p; break;
            default: *q++ = *p; break;
            }
            p++;
        } else {
            *q++ = *p++;
        }
    }
    *q = '\0';
}

static void ical_escape(FILE *fp, const char *s)
{
    for (; s && *s; s++) {
        switch (*s) {
        case '\n': fputs("\\n", fp); break;
        case ',': fputs("\\,", fp); break;
        case ';': fputs("\\;", fp); break;
        case '\\': fputs("\\\\", fp); break;
        default: fputc(*s, fp); break;
        }
    }
}

/* parse DATE-TIME (YYYYMMDDTHHMMSS[Z]) or DATE (YYYYMMDD) */
static long parse_ical_dt(const char *v, int *isdate)
{
    int y, m, d, hh = 0, mm = 0, ss = 0;
    *isdate = 0;
    if (strlen(v) == 8) {
        if (sscanf(v, "%4d%2d%2d", &y, &m, &d) != 3)
            return -1;
        *isdate = 1;
        if (m < 1 || m > 12 || d < 1 || d > 31)
            return -1;
        return date_to_epoch(y, m, d);
    }
    if (sscanf(v, "%4d%2d%2dT%2d%2d%2d", &y, &m, &d, &hh, &mm, &ss) != 6)
        return -1;
    if (m < 1 || m > 12 || d < 1 || d > 31 || hh > 23 || mm > 59 || ss > 60)
        return -1;
    return date_to_epoch(y, m, d) + hh * 3600 + mm * 60 + ss;
}

/* split "NAME;PARAM=..;..:value" */
static void split_prop(char *s, char **name, char **val)
{
    char *q = strchr(s, ':');
    *name = s;
    if (!q) {
        *val = NULL;
        return;
    }
    *q = '\0';
    *val = q + 1;
}

static int has_param(const char *props, const char *key)
{
    char buf[256];
    char *tok, *save = NULL;
    if (!props)
        return 0;
    strncpy(buf, props, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    for (tok = strtok_r(buf, ";", &save); tok; tok = strtok_r(NULL, ";", &save))
        if (!strcasecmp(tok, key))
            return 1;
    return 0;
}

/* parse a duration like P1DT2H3M4S */
static long parse_ical_dur(const char *v)
{
    long res = 0, num;
    const char *p = v;
    int sign = 1;
    if (*p == '-') { sign = -1; p++; }
    else if (*p == '+') p++;
    if (*p != 'P')
        return -1;
    p++;
    while (*p) {
        num = strtol(p, (char **)&p, 10);
        if (p == v)
            return -1;
        if (*p == 'D') { res += num * 86400; p++; }
        else if (*p == 'W') { res += num * 7 * 86400; p++; }
        else if (*p == 'T') { p++; }
        else if (*p == 'H') { res += num * 3600; p++; }
        else if (*p == 'M') { res += num * 60; p++; }
        else if (*p == 'S') { res += num; p++; }
        else break;
    }
    return sign * res;
}

/* ------------------------------------------------------------------ */
/* recurrence conversion                                               */
/* ------------------------------------------------------------------ */
struct rrule {
    int freq;          /* 'D','W','M','Y' or 0 */
    int interval;
    long until;
    int until_set;
    int count;
    int count_set;
    int byday[64];
    int nbyday;
    int bymday[64];
    int nbymday;
    int bymon[64];
    int nbymon;
};

static int rrule_parse(const char *s, struct rrule *r)
{
    char buf[2048], *tok, *save = NULL;
    int badfreq = 0;
    memset(r, 0, sizeof(*r));
    r->interval = 1;
    strncpy(buf, s, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    for (tok = strtok_r(buf, ";", &save); tok; tok = strtok_r(NULL, ";", &save)) {
        char *v = strchr(tok, '=');
        if (!v)
            continue;
        *v++ = '\0';
        if (!strcasecmp(tok, "FREQ")) {
            if (!strcasecmp(v, "DAILY")) r->freq = 'D';
            else if (!strcasecmp(v, "WEEKLY")) r->freq = 'W';
            else if (!strcasecmp(v, "MONTHLY")) r->freq = 'M';
            else if (!strcasecmp(v, "YEARLY")) r->freq = 'Y';
            else { r->freq = 0; badfreq = 1; }
        } else if (!strcasecmp(tok, "INTERVAL")) {
            r->interval = atoi(v);
            if (r->interval < 1)
                r->interval = 1;
        } else if (!strcasecmp(tok, "UNTIL")) {
            int isd;
            long t = parse_ical_dt(v, &isd);
            if (t >= 0) {
                r->until = t;
                r->until_set = 1;
            }
        } else if (!strcasecmp(tok, "COUNT")) {
            r->count = atoi(v);
            r->count_set = 1;
        } else if (!strcasecmp(tok, "BYDAY")) {
            char b2[512], *t2, *sv = NULL;
            strncpy(b2, v, sizeof(b2) - 1);
            b2[sizeof(b2) - 1] = '\0';
            for (t2 = strtok_r(b2, ",", &sv); t2; t2 = strtok_r(NULL, ",", &sv)) {
                char *e = t2;
                int ord = 0, wd = -1, neg = 0, i;
                while (*e && (isdigit((unsigned char)*e) || *e == '-')) {
                    if (*e == '-')
                        neg = 1;
                    e++;
                }
                if (e != t2) {
                    char num[16];
                    int n = (int)(e - t2);
                    memcpy(num, t2, n);
                    num[n] = '\0';
                    ord = atoi(num);
                    if (neg)
                        ord = -ord;
                }
                for (i = 0; i < 7; i++)
                    if (!strcasecmp(e, wday_name[i]))
                        wd = i;
                if (wd < 0)
                    continue;
                if (r->nbyday < 64)
                    r->byday[r->nbyday++] = (ord < 0 ? -(abs(ord) * 7 + wd) : ord * 7 + wd);
            }
        } else if (!strcasecmp(tok, "BYMONTHDAY")) {
            char b2[512], *t2, *sv = NULL;
            strncpy(b2, v, sizeof(b2) - 1);
            b2[sizeof(b2) - 1] = '\0';
            for (t2 = strtok_r(b2, ",", &sv); t2; t2 = strtok_r(NULL, ",", &sv))
                if (r->nbymday < 64)
                    r->bymday[r->nbymday++] = atoi(t2);
        } else if (!strcasecmp(tok, "BYMONTH")) {
            char b2[512], *t2, *sv = NULL;
            strncpy(b2, v, sizeof(b2) - 1);
            b2[sizeof(b2) - 1] = '\0';
            for (t2 = strtok_r(b2, ",", &sv); t2; t2 = strtok_r(NULL, ",", &sv)) {
                int mm = atoi(t2);
                if (mm >= 1 && mm <= 12 && r->nbymon < 64)
                    r->bymon[r->nbymon++] = mm;
            }
        }
        /* WKST, BYSECOND, BYMINUTE, BYHOUR, BYSETPOS, BYYEARDAY, BYWEEKNO: ignored */
    }
    return badfreq ? -1 : (r->freq ? 0 : -1);
}

/* build a recur_t from the parsed rrule */
void ical_rrule_to_recur(item_t *it, const char *rrule, long start)
{
    struct rrule r;
    recur_t *rp;
    int i;
    char buf[2048];

    if (rrule_parse(rrule, &r) < 0)
        return;
    rp = calloc(1, sizeof(recur_t));
    rp->rtype = r.freq;
    rp->freq = r.interval;
    rp->start_day = (int)((start / SECS_DAY) - day_of_epoch(0, 1, 1) * 0);
    {
        int y, m, d;
        epoch_to_date(start, &y, &m, &d);
        rp->start_day = d;
    }
    if (r.until_set) {
        long u = r.until;
        int ut = (int)(u % SECS_DAY);
        long ud = u / SECS_DAY;
        int st = (int)(start % SECS_DAY);
        if (r.count_set && r.count > 0) {
            /* expand to find the last occurrence */
            long occ = start, prev = start;
            int n = 0;
            while (n < r.count) {
                occ = recur_next(it, prev + 1);
                if (occ < 0)
                    break;
                prev = occ;
                n++;
            }
            u = prev;
            ud = u / SECS_DAY;
        }
        rp->until = ud * SECS_DAY;
        (void)ut; (void)st;
    }
    for (i = 0; i < r.nbyday; i++) {
        rp->byday = realloc(rp->byday, (rp->nbyday + 1) * sizeof(int));
        rp->byday[rp->nbyday++] = r.byday[i];
    }
    for (i = 0; i < r.nbymday; i++) {
        rp->bymday = realloc(rp->bymday, (rp->nbymday + 1) * sizeof(int));
        rp->bymday[rp->nbymday++] = r.bymday[i];
    }
    for (i = 0; i < r.nbymon; i++) {
        rp->bymon = realloc(rp->bymon, (rp->nbymon + 1) * sizeof(int));
        rp->bymon[rp->nbymon++] = r.bymon[i];
    }
    if (it->rpt)
        free(it->rpt);
    it->rpt = rp;
    (void)buf;
}
CEOF
echo ok"}

