/* ------------------------------------------------------------------ */
/* import                                                              */
/* ------------------------------------------------------------------ */
struct imp {
    int dump;
    FILE *log;
    int nskipped;
    int napps, nevents, ntodos;
    int nl;
    char *desc;
    char *summary;
    long dtstart;
