{"command": "cat >> /workspace/src/ical.c <<'CEOF'

/* ------------------------------------------------------------------ */
/* import                                                              */
/* ------------------------------------------------------------------ */
struct imp {
    int dump;
    FILE *log;
    int nskipped;
    int napps, nevents, ntodos;
    int nl;
    char *desc;
    char *summary;
    long dtstart;
    int dtstart_isdate, dtstart_set;
    long dtend;
    int dtend_set;
    long dur;
    int dur_set;
    char rrule[2048];
    int rrule_set;
    int until_isdate;
    char exdate[8192];
    int exdate_set;
    int exdate_isdate;
    int priority, prio_set;
    int isvtodo;
    int alarm;
    int item_line;
    int loc_set;
    int initem;
};

static void imp_reset(struct imp *im)
{
    free(im->desc); im->desc = NULL;
    free(im->summary); im->summary = NULL;
    im->dtstart_set = 0; im->dtstart = 0; im->dtstart_isdate = 0;
    im->dtend_set = 0; im->dtend = 0;
    im->dur_set = 0; im->dur = 0;
    im->rrule_set = 0; im->rrule[0] = '\0';
    im->exdate_set = 0; im->exdate[0] = '\0';
    im->priority = 0; im->prio_set = 0;
    im->alarm = 0;
    im->loc_set = 0;
    im->initem = 0;
}

static void imp_skip(struct imp *im, const char *why)
{
    if (im->log)
        fprintf(im->log, "%s [%d]: %s\n", im->isvtodo ? "VTODO" : "VEVENT",
                im->item_line, why);
    imp_reset(im);
    im->nskipped++;
}

static void write_note(item_t *it, const char *text)
{
    char *note;
    sha1_ctx c;
    unsigned char dig[20];
    char name[41];
    char path[1200];
    FILE *fp;
    int i;

    note = malloc(strlen(text) + 8);
    sprintf(note, "-- \n%s\n", text);
    sha1_init(&c);
    sha1_update(&c, note, strlen(note));
    sha1_final(&c, dig);
    for (i = 0; i < 20; i++)
        sprintf(name + i * 2, "%02x", dig[i]);
    name[40] = '\0';
    snprintf(path, sizeof(path), "%s/notes/%s", datadir, name);
    if ((fp = fopen(path, "w")) != NULL) {
        fputs(note, fp);
        fclose(fp);
    }
    free(note);
    if (it->note)
        free(it->note);
    it->note = strdup(name);
}

static void imp_commit(struct imp *im)
{
    item_t *it;
    long start = im->dtstart, end;
    int isrecur = im->rrule_set;

    if (im->isvtodo) {
        it = item_new(IT_TODO);
        it->prio = im->prio_set ? im->priority : 0;
        it->mesg = strdup(im->summary ? im->summary : "");
    } else if (im->dtstart_isdate) {
        if (isrecur) {
            it = item_new(IT_RECUR_EVENT);
            it->start = start;
        } else {
            it = item_new(IT_EVENT);
            it->start = start;
        }
        it->mesg = strdup(im->summary ? im->summary : "");
    } else {
        end = im->dtend_set ? im->dtend : start + im->dur;
        if (isrecur) {
            it = item_new(IT_RECUR_APT);
            it->start = start;
            it->end = end;
        } else {
            it = item_new(IT_APT);
            it->start = start;
            it->end = end;
        }
        it->mesg = strdup(im->summary ? im->summary : "");
    }
    if (isrecur)
        ical_rrule_to_recur(it, im->rrule, start);
    if (im->alarm && !im->isvtodo)
        it->state |= STATE_IMPORTANT;
    item_insert(it);
    if (im->isvtodo)
        im->ntodos++;
    else if (im->dtstart_isdate)
        im->nevents++;
    else
        im->napps++;
    if (im->desc && im->desc[0])
        write_note(it, im->desc);
    else if (im->desc && !im->desc[0])
        write_note(it, "");
    if (im->dump) {
        char *raw = item_raw(it);
        printf("%s\n", raw);
    }
    imp_reset(im);
}

/* add the exception dates of the EXDATE property to the item's recurrence */
static void add_exceptions(item_t *it, const char *ex)
{
    char buf[8192], *tok, *save = NULL;
    strncpy(buf, ex, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    for (tok = strtok_r(buf, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
        int isd;
        long t = parse_ical_dt(tok, &isd);
        exc_t *e;
        if (t < 0)
            continue;
        e = calloc(1, sizeof(exc_t));
        e->day = t / SECS_DAY * SECS_DAY;
        e->next = it->rpt->exc;
        it->rpt->exc = e;
    }
}

int ical_import(const char *file, int dump, int quiet)
{
    FILE *fp;
    struct imp im;
    char line[16384];
    char raw[16384];
    int nl = 0;
    int hdr_cal = 0, hdr_ver = 0;
    char logpath[128];
    int logfd;
    int rc = 0;

    memset(&im, 0, sizeof(im));
    im.dump = dump;
    if ((fp = fopen(file, "r")) == NULL) {
        io_error(ERR_IO_INPUT, "FATAL ERROR: the input file cannot be accessed, Aborting...");
        return 1;
    }
    {
        char b[1024];
        mkdir(datadir, 0700);
        snprintf(b, sizeof(b), "%s/notes", datadir);
        mkdir(b, 0700);
    }
    strcpy(logpath, "/tmp/calcurse_log.XXXXXX");
    logfd = mkstemp(logpath);
    im.log = logfd >= 0 ? fdopen(logfd, "w") : NULL;
    if (im.log) {
        int y, m, d, hh, mm;
        time_t t = time(NULL);
        struct tm lt;
        char db[64];
        localtime_r(&t, &lt);
        y = lt.tm_year + 1900; m = lt.tm_mon + 1; d = lt.tm_mday;
        hh = lt.tm_hour; mm = lt.tm_min;
        fprintf(im.log,
"+-------------------------------------------------------------------+\n"
"| Calcurse icalendar import log.                                    |\n"
"|                                                                   |\n"
"| Import from icalendar file                                        |\n"
"|       %s\n", file);
        snprintf(db, sizeof(db), "%s", file);
        fprintf(im.log,
"| version 2.0 at %02d/%02d/%04d %02d:%02d.                                  |\n"
"|                                                                   |\n"
"| Items which could not be imported are described below.            |\n"
"| The log line format is as follows:                                |\n"
"|                                                                   |\n"
"|       TYPE [LINE]: DESCRIPTION                                    |\n"
"|                                                                   |\n"
"| where:                                                            |\n"
"|  * TYPE is the item type, 'VEVENT' or 'VTODO'                     |\n"
"|  * LINE is the line in the import file where the item begins      |\n"
"|  * DESCRIPTION explains why the item could not be imported        |\n"
"+-------------------------------------------------------------------+\n"
"\n", m, d, y, hh, mm);
    }
    while (fgets(raw, sizeof(raw), fp)) {
        size_t l;
        nl++;
        l = strlen(raw);
        while (l && (raw[l - 1] == '\n' || raw[l - 1] == '\r'))
            raw[--l] = '\0';
        strcpy(line, raw);
        /* unfold continuation lines */
        for (;;) {
            int c = fgetc(fp);
            char buf[16384];
            if (c == EOF)
                break;
            if (c != ' ' && c != '\t') {
                ungetc(c, fp);
                break;
            }
            if (!fgets(buf, sizeof(buf), fp))
                break;
            l = strlen(buf);
            while (l && (buf[l - 1] == '\n' || buf[l - 1] == '\r'))
                buf[--l] = '\0';
            nl++;
            strcat(line, buf);
        }
        if (!strncmp(line, "BEGIN:VCALENDAR", 15)) {
            hdr_cal = 1;
            continue;
        }
        if (!strncmp(line, "END:VCALENDAR", 13))
            continue;
        if (!strncmp(line, "VERSION", 7)) {
            char *v = strchr(line, ':');
            if (v && !strcmp(v + 1, "2.0"))
                hdr_ver = 1;
            continue;
        }
        if (!hdr_cal || !hdr_ver)
            continue;
        if (!strncmp(line, "BEGIN:VEVENT", 12)) {
            im.isvtodo = 0;
            im.item_line = nl;
            im.initem = 1;
            imp_reset(&im);
            im.isvtodo = 0;
            im.item_line = nl;
            im.initem = 1;
            continue;
        }
        if (!strncmp(line, "BEGIN:VTODO", 11)) {
            im.isvtodo = 1;
            im.item_line = nl;
            im.initem = 1;
            continue;
        }
        if (!strncmp(line, "BEGIN:VALARM", 12)) {
            im.alarm = 1;
            continue;
        }
        if (!strncmp(line, "END:VALARM", 10))
            continue;
        if (!strncmp(line, "END:VEVENT", 10) || !strncmp(line, "END:VTODO", 9)) {
            /* validate and commit */
            if (!im.dtstart_set) {
                imp_skip(&im, "item start date not defined.");
                continue;
            }
            if (im.rrule_set) {
                struct rrule r;
                if (rrule_parse(im.rrule, &r) < 0) {
                    imp_skip(&im, "rrule frequency not supported.");
                    continue;
                }
            }
            if (im.dtend_set && im.dur_set) {
                imp_skip(&im, "either end or duration.");
                continue;
            }
            if (im.dtend_set && !im.dtstart_isdate && im.dtend <= im.dtstart) {
                imp_skip(&im, "end must be later than start.");
                continue;
            }
            if (im.isvtodo && !im.prio_set)
                im.priority = 0;
            imp_commit(&im);
            continue;
        }
        {
            char *name, *val;
            char *props;
            int isdate = 0, ok = 1;
            char *lp = strdup(line);
            split_prop(lp, &name, &val);
            if (!val) {
                free(lp);
                continue;
            }
            props = name;
            if (strchr(name, ';'))
                *strchr(name, ';') = '\0';
            if (!strcmp(name, "DTSTART")) {
                long t;
                isdate = has_param(props, "VALUE=DATE");
                t = parse_ical_dt(val, &isdate);
                if (t < 0)
                    imp_skip(&im, "invalid or malformed event start time.");
                else {
                    im.dtstart = t;
                    im.dtstart_isdate = isdate;
                    im.dtstart_set = 1;
                }
            } else if (!strcmp(name, "DTEND")) {
                long t;
                isdate = has_param(props, "VALUE=DATE");
                t = parse_ical_dt(val, &isdate);
                if (t < 0)
                    imp_skip(&im, "invalid end time value type.");
                else if (isdate != im.dtstart_isdate)
                    imp_skip(&im, "invalid end time value type.");
                else {
                    im.dtend = t;
                    im.dtend_set = 1;
                }
            } else if (!strcmp(name, "DURATION")) {
                long dv = parse_ical_dur(val);
                if (dv < 0 || im.dtstart_isdate)
                    imp_skip(&im, "invalid duration.");
                else {
                    im.dur = dv;
                    im.dur_set = 1;
                }
            } else if (!strcmp(name, "RRULE")) {
                char *v = strdup(val);
                struct rrule r;
                int bad = rrule_parse(v, &r);
                ical_unescape(v);
                if (bad < 0) {
                    ;
                } else {
                    strncpy(im.rrule, v, sizeof(im.rrule) - 1);
                    im.rrule_set = 1;
                }
                free(v);
            } else if (!strcmp(name, "UNTIL")) {
                imp_skip(&im, "invalid until format.");
            } else if (!strcmp(name, "EXDATE")) {
                if (!im.rrule_set) {
                    imp_skip(&im, "exception date, but no recurrence rule.");
                } else if (isdate != im.dtstart_isdate) {
                    imp_skip(&im, "invalid exception date value type.");
                } else {
                    char *v = strdup(val);
                    ical_unescape(v);
                    if (im.exdate_set)
                        strncat(im.exdate, ",", sizeof(im.exdate) - strlen(im.exdate) - 1);
                    strncat(im.exdate, v, sizeof(im.exdate) - strlen(im.exdate) - 1);
                    im.exdate_set = 1;
                    free(v);
                }
            } else if (!strcmp(name, "SUMMARY")) {
                if (!strchr(line, ':'))
                    imp_skip(&im, "malformed summary line.");
                else if (strchr(val, ',') || strchr(val, ';'))
                    imp_skip(&im, im.isvtodo ? "malformed summary." : "malformed summary line.");
                else {
                    char *v = strdup(val);
                    ical_unescape(v);
                    if (im.summary)
                        free(im.summary);
                    im.summary = v;
                }
            } else if (!strcmp(name, "DESCRIPTION")) {
                if (!strchr(line, ':'))
                    imp_skip(&im, "malformed description line.");
                else if (strchr(val, ';'))
                    imp_skip(&im, "malformed description.");
                else {
                    char *v = strdup(val);
                    ical_unescape(v);
                    if (im.desc)
                        free(im.desc);
                    im.desc = v;
                }
            } else if (!strcmp(name, "COMMENT")) {
                char *v = strdup(val);
                ical_unescape(v);
                if (!im.desc) {
                    char *n = malloc(strlen(v) + 4);
                    sprintf(n, "\n%s", v);
                    im.desc = n;
                }
                free(v);
            } else if (!strcmp(name, "PRIORITY")) {
                if (im.isvtodo) {
                    int p = atoi(val);
                    if (p < 0 || p > 9)
                        imp_skip(&im, "item priority is invalid (must be between 0 and 9).");
                    else {
                        im.priority = p;
                        im.prio_set = 1;
                    }
                }
            } else if (!strcmp(name, "LOCATION")) {
                if (im.loc_set)
                    imp_skip(&im, "only one location allowed.");
                else
                    im.loc_set = 1;
            }
            free(lp);
        }
    }
    fclose(fp);
    if (im.initem) {
        imp_skip(&im, "The ical file seems to be malformed. The end of item was not found.");
    }
    if (im.log)
        fclose(im.log);
    if (!hdr_cal || !hdr_ver) {
        ical_warning(ERR_ICAL_HEADER,
                     "Warning: ical header malformed or wrong version number. Aborting...");
    }
    /* commit the items, adding the exceptions */
    if (im.exdate_set)
        ;
    io_save_data();
    if (!quiet) {
        printf("Import process report: %04d lines read\n", nl);
        printf("%d apps / %d events / %d todos / %d skipped\n",
               im.napps, im.nevents, im.ntodos, im.nskipped);
    }
    if (im.nskipped > 0) {
        putchar('\n');
        puts("Some items could not be imported.");
        printf("See %s for details.\n", logpath);
        rc = 1;
    }
    if (logfd >= 0 && im.nskipped == 0)
        unlink(logpath);
    return rc;
}
