{"command": "cat >> /workspace/src/ical.c <<'CEOF'

/* ------------------------------------------------------------------ */
/* export                                                              */
/* ------------------------------------------------------------------ */
static void write_rrule(FILE *fp, item_t *it, int isdate)
{
    recur_t *r = it->rpt;
    int i, first = 1;
    fprintf(fp, "RRULE:FREQ=%c%c%c%cLY", r->rtype == REC_DAILY ? 'D' : 0, 0, 0, 0);
    (void)first;
    (void)i;
}

static void export_rrule(FILE *fp, item_t *it, int isdate)
{
    recur_t *r = it->rpt;
    static const char *freqname[4] = { "DAILY", "WEEKLY", "MONTHLY", "YEARLY" };
    int fi = r->rtype == REC_DAILY ? 0 : (r->rtype == REC_WEEKLY ? 1 :
            (r->rtype == REC_MONTHLY ? 2 : 3));
    fprintf(fp, "RRULE:FREQ=%s", freqname[fi]);
    if (r->freq != 1)
        fprintf(fp, ";INTERVAL=%d", r->freq);
    if (r->until) {
        int y, m, d;
        epoch_to_date(r->until, &y, &m, &d);
        if (isdate)
            fprintf(fp, ";UNTIL=%04d%02d%02d", y, m, d);
        else
            fprintf(fp, ";UNTIL=%04d%02d%02dT%02d%02d%02d", y, m, d,
                    (int)((it->start % SECS_DAY) / 3600),
                    (int)((it->start % 3600) / 60), 0);
    }
    if (r->nbymday) {
        int i;
        fprintf(fp, ";BYMONTHDAY=");
        for (i = 0; i < r->nbymday; i++)
            fprintf(fp, "%s%d", i ? "," : "", r->bymday[i]);
    }
    if (r->nbymon) {
        int i;
        fprintf(fp, ";BYMONTH=");
        for (i = 0; i < r->nbymon; i++)
            fprintf(fp, "%s%d", i ? "," : "", r->bymon[i]);
    }
    if (r->nbyday) {
        int i;
        fprintf(fp, ";BYDAY=");
        for (i = 0; i < r->nbyday; i++) {
            int v = r->byday[i];
            int a = v < 0 ? -v : v;
            int wd = a % 7, ord = a / 7;
            fprintf(fp, "%s%s", i ? "," : "",
                    v < 0 ? "-" : (ord ? "+" : ""));
            if (ord)
                fprintf(fp, "%d", ord);
            fputs(wday_name[wd], fp);
        }
    }
}

static void export_ical_item(FILE *fp, item_t *it, int uid)
{
    int y, m, d;
    char hash[41];
    epoch_to_date(it->start, &y, &m, &d);
    fputs("BEGIN:VEVENT\n", fp);
    if (uid) {
        hash_of(it, hash);
        fprintf(fp, "UID:%s\n", hash);
    }
    if (it->type == IT_EVENT || it->type == IT_RECUR_EVENT) {
        fprintf(fp, "DTSTART;VALUE=DATE:%04d%02d%02d\n", y, m, d);
    } else {
        fprintf(fp, "DTSTART:%04d%02d%02dT%02d%02d%02d\n", y, m, d,
                (int)((it->start % SECS_DAY) / 3600),
                (int)((it->start % 3600) / 60), 0);
        {
            long dur = it->end - it->start;
            fprintf(fp, "DURATION:P%ldDT%02ldH%02ldM%02ldS\n", dur / SECS_DAY,
                    (dur % SECS_DAY) / 3600, (dur % 3600) / 60, dur % 60);
        }
    }
    if (it->rpt) {
        export_rrule(fp, it, it->type == IT_EVENT || it->type == IT_RECUR_EVENT);
        if (it->rpt->exc) {
            exc_t *e;
            int first = 1;
            fprintf(fp, "EXDATE:");
            for (e = it->rpt->exc; e; e = e->next) {
                int ey, em, ed;
                epoch_to_date(e->day, &ey, &em, &ed);
                if (!first)
                    fputc(',', fp);
                first = 0;
                if (it->type == IT_EVENT || it->type == IT_RECUR_EVENT)
                    fprintf(fp, "%04d%02d%02d", ey, em, ed);
                else
                    fprintf(fp, "%04d%02d%02dT%02d%02d%02d", ey, em, ed,
                            (int)((it->start % SECS_DAY) / 3600),
                            (int)((it->start % 3600) / 60), 0);
            }
            fputc('\n', fp);
        }
    }
    fputs("SUMMARY:", fp);
    ical_escape(fp, it->mesg);
    fputc('\n', fp);
    fputs("END:VEVENT\n", fp);
}

static void export_ical_todo(FILE *fp, item_t *it, int uid)
{
    char hash[41];
    fputs("BEGIN:VTODO\n", fp);
    if (uid) {
        hash_of(it, hash);
        fprintf(fp, "UID:%s\n", hash);
    }
    fprintf(fp, "PRIORITY:%d\n", it->prio < 0 ? -it->prio : it->prio);
    if (it->prio < 0)
        fputs("STATUS:COMPLETED\n", fp);
    fputs("SUMMARY:", fp);
    ical_escape(fp, it->mesg);
    fputc('\n', fp);
    fputs("END:VTODO\n", fp);
}

void ical_export(void)
{
    item_t *p;
    fputs("BEGIN:VCALENDAR\n", stdout);
    fputs("VERSION:2.0\n", stdout);
    fputs("PRODID:-//calcurse//NONSGML v" CALCURSE_VERSION "//EN\n", stdout);
    for (p = recur_events; p; p = p->next)
        export_ical_item(stdout, p, args.export_uid);
    for (p = events; p; p = p->next)
        export_ical_item(stdout, p, args.export_uid);
    for (p = recur_apoints; p; p = p->next)
        export_ical_item(stdout, p, args.export_uid);
    for (p = apoints; p; p = p->next)
        export_ical_item(stdout, p, args.export_uid);
    for (p = todolist; p; p = p->next)
        export_ical_todo(stdout, p, args.export_uid);
    fputs("END:VCALENDAR\n", stdout);
}

/* ------------------------------------------------------------------ */
/* pcal export                                                         */
/* ------------------------------------------------------------------ */
static const char *pmon[12] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
static const char *pwday[7] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };

static int pcal_wday_val(int v)
{
    int a = v < 0 ? -v : v;
    return a % 7;
}

static int pcal_ord(int v)
{
    int a = v < 0 ? -v : v;
    return a / 7;
}

static void pcal_recur_event(FILE *fp, item_t *it)
{
    recur_t *r = it->rpt;
    int y, m, d;
    epoch_to_date(it->start, &y, &m, &d);
    if (r->until)
        return;
    switch (r->rtype) {
    case REC_MONTHLY:
        if (r->nbymday) {
            int i;
            for (i = 0; i < r->nbymday; i++) {
                int v = r->bymday[i];
                if (v > 0)
                    fprintf(fp, "day on all %d  %s\n", v, it->mesg);
                else
                    fprintf(fp, "day on all %d(-)  %s\n", -v, it->mesg);
            }
        } else if (r->nbyday) {
            int i;
            for (i = 0; i < r->nbyday; i++) {
                int v = r->byday[i];
                int wd = pcal_wday_val(v), ord = pcal_ord(v);
                if (ord > 0)
                    fprintf(fp, "all %s on_or_after %s %d  %s\n", pwday[wd], pmon[m - 1], ord, it->mesg);
                else if (ord < 0)
                    fprintf(fp, "all %s on_or_before %s %d  %s\n", pwday[wd], pmon[m - 1], -ord, it->mesg);
                else
                    fprintf(fp, "all %s on_or_after %s  %s\n", pwday[wd], pmon[m - 1], it->mesg);
            }
        } else
