                    fprintf(fp, "all %s on_or_after %s %d  %s\n", pwday[wd], pmon[m - 1], ord, it->mesg);
                else if (ord < 0)
                    fprintf(fp, "all %s on_or_before %s %d  %s\n", pwday[wd], pmon[m - 1], -ord, it->mesg);
                else
                    fprintf(fp, "all %s on_or_after %s  %s\n", pwday[wd], pmon[m - 1], it->mesg);
            }
        } else
            fprintf(fp, "day on all %d  %s\n", d, it->mesg);
        break;
    case REC_WEEKLY:
        if (r->nbyday) {
            int i;
            for (i = 0; i < r->nbyday; i++)
                fprintf(fp, "all %s on_or_after %s %d  %s\n",
                        pwday[pcal_wday_val(r->byday[i])], pmon[m - 1], d, it->mesg);
        } else
            fprintf(fp, "all %s on_or_after %s %d  %s\n", pwday[pcal_wday_val(d - 1)], pmon[m - 1], d, it->mesg);
        break;
    case REC_YEARLY:
        fprintf(fp, "%s %d  %s\n", pmon[m - 1], d, it->mesg);
        break;
    default:
        break;
    }
}

void pcal_export(void)
{
    item_t *p;
    int y, m, d;
    fputs("# calcurse pcal export\n\n", stdout);
    fputs("# =======\n# options\n# =======\n", stdout);
    printf("opt -A -K -l -m -F %s\n", conf.firstdayofweek ? "Monday" : "Sunday");
    fputs("# Display week number (i.e. 1-52) on every Monday\n", stdout);
    fputs("all monday in all week %w\n", stdout);
    fputs("\n\n# =============\n# Recur. Events\n# =============\n", stdout);
    fputs("# (pcal does not support from..until dates specification\n", stdout);
    for (p = recur_events; p; p = p->next)
        pcal_recur_event(stdout, p);
    fputs("\n# ======\n# Events\n# ======\n", stdout);
    for (p = events; p; p = p->next) {
        epoch_to_date(p->start, &y, &m, &d);
        printf("%s %d  %s\n", pmon[m - 1], d, p->mesg);
    }
    fputs("\n\n# ==============\n# Recur. Apoints\n# ==============\n", stdout);
    fputs("# (pcal does not support from..until dates specification\n", stdout);
    fputs("\n# ============\n# Appointments\n# ============\n", stdout);
    for (p = apoints; p; p = p->next) {
        epoch_to_date(p->start, &y, &m, &d);
        printf("%s %d  (%02d:%02d -> %02d:%02d) %s\n", pmon[m - 1], d,
               (int)((p->start % SECS_DAY) / 3600), (int)((p->start % 3600) / 60),
               (int)((p->end % SECS_DAY) / 3600), (int)((p->end % 3600) / 60),
               p->mesg);
    }
    fputs("\n#\n# Todos\n#\n", stdout);
    for (p = todolist; p; p = p->next)
        if (p->prio > 0)
            printf("note all  %d. %s\n", p->prio, p->mesg);
    fputc('\n', stdout);
}

void import_run(void)
{
    if (ical_import(args.import_file, args.dump_imported, args.quiet))
        exit(1);
}

void export_run(void)
{
    if (args.export_format)
        pcal_export();
    else
        ical_export();
}

void gc_run(void)
{
    io_garbage_collect();
}

void status_run(void)
{
    char path[1024];
    FILE *fp;
    int pid;
    snprintf(path, sizeof(path), "%s/.calcurse.pid", datadir);
    if ((fp = fopen(path, "r")) == NULL) {
        puts("calcurse is not running");
        return;
    }
    if (fscanf(fp, "%d", &pid) != 1 || kill(pid, 0) != 0) {
        puts("calcurse is not running");
        fclose(fp);
        return;
    }
    printf("calcurse is running (pid %d)\n", pid);
    fclose(fp);
}

void daemon_run(void)
{
    /* nothing to notify: exit immediately, like the reference implementation */
    exit(0);
}
