{"command": "cd /workspace/src && rm -f io.c.bak && cat > query.c <<'CEOF'
#define _GNU_SOURCE
#include "calcurse.h"
#include "query.h"
#include "io.h"
#include "dates.h"
#include "args.h"
#include <ctype.h>
#include <stdarg.h>
#include <regex.h>

int grep_mode = 0;
long query_now;

filter_t flt;
format_t fmts;

static long print_remaining;

void args_error(int line, const char *fmt, ...);
void io_error(int line, const char *fmt, ...);
void recur_error(int line, const char *fmt, ...);

/* ------------------------------------------------------------------ */
/* extended time format                                                */
/* ------------------------------------------------------------------ */
static void print_component(FILE *out, long v, int nopad)
{
    if (nopad)
        fprintf(out, "%ld", v);
    else
        fprintf(out, "%02ld", v);
}

/* render a duration/remaining value with the extended format */
static void render_ext(FILE *out, long val, const char *fmt)
{
    const char *p = fmt;
    long rem;
    long d, h, m, s;

    while (*p) {
        if (*p != '%') {
            fputc(*p++, out);
            continue;
        }
        p++;
        {
            int nopad = 0, ext = 0;
            if (*p == '-') { nopad = 1; p++; }
            if (*p == 'E') { ext = 1; p++; }
            if (*p == 'd' || *p == 'H' || *p == 'M' || *p == 'S') {
                char c = *p++;
                if (ext) {
                    rem = val;
                    d = rem / 86400;
                    rem %= 86400;
                    h = rem / 3600;
                    rem %= 3600;
                    m = rem / 60;
                    s = rem % 60;
                } else {
                    d = val / 86400;
                    rem = val % 86400;
                    h = rem / 3600; rem %= 3600;
                    m = rem / 60; rem %= 60;
                    s = rem;
                    if (c == 'H') h %= 24;
                    else if (c == 'M') m %= 60;
                    else if (c == 'S') s = rem;
                }
                print_component(out, c == 'd' ? d : (c == 'H' ? h : (c == 'M' ? m : s)), nopad);
                continue;
            }
            if (*p == '%') {
                p++;
                fputc('%', out);
                continue;
            }
            fputc('?', out);
            if (*p)
                p++;
        }
    }
}

static void render_clocktime(FILE *out, long val)
{
    fprintf(out, "%ld:%02ld", val / 3600, (val % 3600) / 60);
}

static void render_strftime(FILE *out, long t, const char *fmt, long disp_day)
{
    if (!fmt || !*fmt || !strcmp(fmt, "default")) {
        long ds = disp_day * SECS_DAY;
        long de = ds + SECS_DAY - 1;
        if (t < ds || t > de)
            fputs("..:..", out);
        else {
            struct tm tm;
            time_t tt = (time_t)t;
            char buf[32];
            localtime_r(&tt, &tm);
            strftime(buf, sizeof(buf), "%H:%M", &tm);
            fputs(buf, out);
        }
        return;
    }
    if (!strcmp(fmt, "epoch")) {
        fprintf(out, "%ld", t);
        return;
    }
    {
        struct tm tm;
        time_t tt = (time_t)t;
        char buf[256];
        localtime_r(&tt, &tm);
        strftime(buf, sizeof(buf), fmt, &tm);
        fputs(buf, out);
    }
}

/* ------------------------------------------------------------------ */
/* format renderer                                                     */
/* ------------------------------------------------------------------ */
void fmt_render(item_t *it, long occ_start, long occ_end, long disp_day,
                const char *fmt, FILE *out)
{
    const char *p = fmt;
    char *raw;
    char hashbuf[41];
    int is_apt = (it->type == IT_APT || it->type == IT_RECUR_APT);

    while (*p) {
        if (*p != '%') {
            fputc(*p++, out);
            continue;
        }
        p++;
        switch (*p) {
        case 'm':
            fputs(it->mesg ? it->mesg : "", out);
            break;
        case 'n':
            fprintf(out, "%s", it->note ? it->note : "(null)");
            break;
        case 'N':
            {
                char *c = note_read(it->note);
                if (c)
                    fputs(c, out);
            }
            break;
        case 'p':
            if (it->type == IT_TODO)
                fprintf(out, "%d", it->prio < 0 ? -it->prio : it->prio);
            else
                fputc('?', out);
            break;
        case 'd':
            if (is_apt)
                fprintf(out, "%ld", occ_end - occ_start);
            else
                fputc('?', out);
            break;
        case 's':
            if (is_apt)
                fprintf(out, "%ld", occ_start);
            else
                fputc('?', out);
            break;
        case 'e':
            if (is_apt)
                fprintf(out, "%ld", occ_end);
            else
                fputc('?', out);
            break;
