/* ------------------------------------------------------------------ */
/* filters                                                             */
/* ------------------------------------------------------------------ */
static int regex_match(const char *s)
{
    regex_t re;
    int r;
    if (!flt.pattern)
        return 1;
    if (regcomp(&re, flt.pattern, REG_EXTENDED | REG_NOSUB) != 0)
        return 1;
    r = regexec(&re, s, 0, NULL, 0);
    regfree(&re);
    return r == 0;
}

static int filter_item_inner(item_t *it)
{
    long st = it->start, en;
    char hashbuf[41];

    if (it->type == IT_EVENT || it->type == IT_RECUR_EVENT)
        en = it->start + SECS_DAY - 1;
    else
        en = it->end;

    if (!regex_match(it->mesg ? it->mesg : ""))
        return 0;
    if (flt.hash) {
        const char *h = flt.hash;
        int neg = 0;
        if (*h == '!') { neg = 1; h++; }
        hash_of(it, hashbuf);
        if ((!neg && strncmp(hashbuf, h, strlen(h)) != 0) ||
            (neg && strncmp(hashbuf, h, strlen(h)) == 0))
            return 0;
    }
    if (it->type != IT_TODO) {
        if (flt.start_from_set && st < flt.start_from)
            return 0;
        if (flt.start_to_set && st > flt.start_to)
            return 0;
        if (flt.start_after_set && st <= flt.start_after)
            return 0;
        if (flt.start_before_set && st >= flt.start_before)
            return 0;
        if (flt.start_range_set && (st < flt.start_r1 || st > flt.start_r2))
            return 0;
        if (flt.end_from_set && en < flt.end_from)
            return 0;
        if (flt.end_to_set && en > flt.end_to)
            return 0;
        if (flt.end_after_set && en <= flt.end_after)
            return 0;
        if (flt.end_before_set && en >= flt.end_before)
            return 0;
        if (flt.end_range_set && (en < flt.end_r1 || en > flt.end_r2))
            return 0;
    }
    if (it->type == IT_TODO) {
        if (flt.prio_set && (it->prio < 0 ? -it->prio : it->prio) != flt.prio)
            return 0;
        if (flt.completed == 1 && it->prio >= 0)
            return 0;
        if (flt.completed == 0 && it->prio < 0)
            return 0;
    }
    return 1;
}

int filter_item(item_t *it)
{
    int ok = filter_item_inner(it);
    if (flt.invert)
        ok = !ok;
    return ok;
}

/* ------------------------------------------------------------------ */
