    if (it->type == IT_EVENT || it->type == IT_RECUR_EVENT)
        en = it->start + SECS_DAY - 1;
    else
        en = it->end;

    if (!regex_match(it->mesg ? it->mesg : ""))
        return 0;
    if (flt.hash) {
        const char *h = flt.hash;
        int neg = 0;
        if (*h == '!') { neg = 1; h++; }
        hash_of(it, hashbuf);
        if ((!neg && strncmp(hashbuf, h, strlen(h)) != 0) ||
            (neg && strncmp(hashbuf, h, strlen(h)) == 0))
            return 0;
    }
    if (it->type != IT_TODO) {
        if (flt.start_from_set && st < flt.start_from)
            return 0;
        if (flt.start_to_set && st > flt.start_to)
            return 0;
        if (flt.start_after_set && st <= flt.start_after)
            return 0;
        if (flt.start_before_set && st >= flt.start_before)
            return 0;
        if (flt.start_range_set && (st < flt.start_r1 || st > flt.start_r2))
            return 0;
        if (flt.end_from_set && en < flt.end_from)
            return 0;
        if (flt.end_to_set && en > flt.end_to)
            return 0;
        if (flt.end_after_set && en <= flt.end_after)
            return 0;
        if (flt.end_before_set && en >= flt.end_before)
            return 0;
        if (flt.end_range_set && (en < flt.end_r1 || en > flt.end_r2))
            return 0;
    }
    if (it->type == IT_TODO) {
        if (flt.prio_set && (it->prio < 0 ? -it->prio : it->prio) != flt.prio)
            return 0;
        if (flt.completed == 1 && it->prio >= 0)
            return 0;
        if (flt.completed == 0 && it->prio < 0)
            return 0;
    }
    return 1;
}

int filter_item(item_t *it)
{
    int ok = filter_item_inner(it);
    if (flt.invert)
        ok = !ok;
    return ok;
}

/* ------------------------------------------------------------------ */
/* queries                                                             */
/* ------------------------------------------------------------------ */
static void set_raw_formats(void)
{
    fmts.apt = DEF_FMT_RAW; fmts.recur_apt = DEF_FMT_RAW;
    fmts.event = DEF_FMT_RAW; fmts.recur_event = DEF_FMT_RAW;
    fmts.todo = DEF_FMT_RAW;
}

static int may_print(void)
{
    if (args.limit_set && print_remaining <= 0)
        return 0;
    if (args.limit_set)
        print_remaining--;
    return 1;
}

static void day_range(long *from, long *to)
{
    long today = query_now / SECS_DAY * SECS_DAY;
    *from = today;
    *to = today;
    if (args.op == OP_APPOINT)
        return;
    if (args.from_set)
        *from = args.from;
    if (args.op == OP_DAY) {
        if (args.day_is_date) {
            *from = args.day;
            *to = args.day;
        } else if (args.day > 0) {
            *to = today + (args.day - 1) * SECS_DAY;
        } else {
            *from = today + (args.day + 1) * SECS_DAY;
        }
        return;
    }
    if (args.op == OP_RANGE) {
        if (args.range > 0)
            *to = today + (args.range - 1) * SECS_DAY;
        else
            *from = today + (args.range + 1) * SECS_DAY;
        return;
    }
    if (args.days_set) {
        if (args.days > 0)
            *to = *from + (args.days - 1) * SECS_DAY;
        else
            *from = *from + (args.days + 1) * SECS_DAY;
        return;
    }
    if (args.to_set)
        *to = args.to;
    if (args.from_set && !args.to_set && !args.days_set)
        *to = *from;
}

static void print_todo_section(int *first)
{
    item_t *p;
    int n = 0;
    for (p = todolist; p; p = p->next)
        if (filter_item(p))
            n++;
    if (n == 0)
        return;
    if (flt.completed == 1)
        fputs("completed tasks:\n", stdout);
    else
        fputs("to do:\n", stdout);
    for (p = todolist; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, 0, 0, 0, fmts.todo, stdout);
    }
    *first = 0;
}

struct dayitem {
    item_t *it;
    long occ;
    int type;
};

static void print_day(long day, int *first)
{
    long ds = day * SECS_DAY;
    long de = ds + SECS_DAY - 1;
    item_t *p;
    int cnt = 0;
    char dbuf[64];
    struct dayitem list[4096];
    int n = 0, i, j;

    for (p = recur_events; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ < 0 || occ > de)
            continue;
        if (!filter_item(p))
            continue;
        cnt++;
        if (n < 4096) { list[n].it = p; list[n].occ = occ; list[n].type = IT_RECUR_EVENT; n++; }
    }
    for (p = events; p; p = p->next) {
        if (p->start < ds || p->start > de)
            continue;
        if (!filter_item(p))
            continue;
        cnt++;
        if (n < 4096) { list[n].it = p; list[n].occ = p->start; list[n].type = IT_EVENT; n++; }
    }
    for (p = recur_apoints; p; p = p->next) {
        long occ = recur_next(p, ds);
        if (occ < 0 || occ > de || occ + (p->end - p->start) < ds)
            continue;
        if (!filter_item(p))
            continue;
        cnt++;
        if (n < 4096) { list[n].it = p; list[n].occ = occ; list[n].type = IT_RECUR_APT; n++; }
    }
    for (p = apoints; p; p = p->next) {
        if (p->end < ds || p->start > de)
            continue;
        if (!filter_item(p))
            continue;
        cnt++;
        if (n < 4096) { list[n].it = p; list[n].occ = p->start; list[n].type = IT_APT; n++; }
    }
    if (cnt == 0)
        return;
    if (!*first)
        putchar('\n');
    date_str(dbuf, sizeof(dbuf), ds);
    printf("%s:\n", dbuf);
    *first = 0;

    for (i = 0; i < n; i++) {
        if (list[i].type != IT_RECUR_EVENT && list[i].type != IT_EVENT)
            continue;
        if (!may_print())
            continue;
        fmt_render(list[i].it, list[i].occ, list[i].occ, day,
                   list[i].type == IT_EVENT ? fmts.event : fmts.recur_event, stdout);
    }
    for (i = 0; i < n; i++) {
        if (list[i].type != IT_RECUR_APT && list[i].type != IT_APT)
            continue;
        for (j = i - 1; j >= 0 && (list[j].type == IT_RECUR_APT || list[j].type == IT_APT) &&
                        list[j].occ > list[i].occ; j--)
            ;
        {
            struct dayitem tmp = list[i];
            int k;
            for (k = i; k > j + 1; k--)
                list[k] = list[k - 1];
            list[j + 1] = tmp;
        }
    }
    for (i = 0; i < n; i++) {
        if (list[i].type != IT_RECUR_APT && list[i].type != IT_APT)
            continue;
        if (!may_print())
            continue;
        fmt_render(list[i].it, list[i].occ, list[i].occ + (list[i].it->end - list[i].it->start),
                   day, list[i].type == IT_APT ? fmts.apt : fmts.recur_apt, stdout);
    }
}

void query_run(void)
{
    long from, to, day;
    int first = 1;

    query_now = time(NULL);
    if (grep_mode)
        set_raw_formats();
    print_remaining = args.limit_set ? args.limit : -1;
    if (flt.mask & FILTER_TODO)
        print_todo_section(&first);
    if (flt.mask & (FILTER_EVENT | FILTER_APT | FILTER_RECUR_EVENT | FILTER_RECUR_APT)) {
        day_range(&from, &to);
        for (day = from; day <= to; day += SECS_DAY)
            print_day(day / SECS_DAY, &first);
    }
}

/* ------------------------------------------------------------------ */
/* -G : print items in data file format                                */
/* ------------------------------------------------------------------ */
void grep_run(void)
{
    item_t *p;
    query_now = time(NULL);
    set_raw_formats();
    print_remaining = args.limit_set ? args.limit : -1;
    for (p = todolist; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, 0, 0, 0, fmts.todo, stdout);
    }
    for (p = recur_events; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->start, p->start / SECS_DAY, fmts.recur_event, stdout);
    }
    for (p = recur_apoints; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->end, p->start / SECS_DAY, fmts.recur_apt, stdout);
    }
    for (p = apoints; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->end, p->start / SECS_DAY, fmts.apt, stdout);
    }
    for (p = events; p; p = p->next) {
        if (!filter_item(p))
            continue;
        if (!may_print())
            continue;
        fmt_render(p, p->start, p->start, p->start / SECS_DAY, fmts.event, stdout);
    }
}

/* ------------------------------------------------------------------ */
/* -P : purge                                                          */
/* ------------------------------------------------------------------ */
static void relink(item_t **head, item_t **tail)
{
    item_t *p;
    *tail = NULL;
    for (p = *head; p; p = p->next)
        *tail = p;
}

void purge_run(void)
{
    item_t *keep_head[5], *keep_tail[5];
    int i;
    item_t *p, *n;
    item_t **src;

    for (i = 0; i < 5; i++)
        keep_head[i] = keep_tail[i] = NULL;
    for (i = 0; i < 5; i++) {
        switch (i) {
        case 0: src = &todolist; break;
        case 1: src = &recur_events; break;
        case 2: src = &recur_apoints; break;
        case 3: src = &apoints; break;
        default: src = &events; break;
        }
        for (p = *src; p; p = n) {
            n = p->next;
            if (!filter_item(p)) {
                if (keep_tail[i])
                    keep_tail[i]->next = p;
                else
                    keep_head[i] = p;
                keep_tail[i] = p;
                p->next = NULL;
            } else {
                item_free(p);
            }
        }
        *src = keep_head[i];
    }
    relink(&todolist, &keep_tail[0]);
    relink(&recur_events, &keep_tail[1]);
    relink(&recur_apoints, &keep_tail[2]);
    relink(&apoints, &keep_tail[3]);
    relink(&events, &keep_tail[4]);
    io_save_data();
}

/* ------------------------------------------------------------------ */
/* -n : next appointment                                               */
/* ------------------------------------------------------------------ */
void next_run(void)
{
    item_t *p;
    long best = -1;
    char *bestmsg = NULL;
    long delta;

    query_now = time(NULL);
    for (p = apoints; p; p = p->next)
        if (p->start > query_now && p->start <= query_now + 24 * 3600)
            if (best < 0 || p->start < best) {
                best = p->start;
                bestmsg = p->mesg;
            }
    for (p = recur_apoints; p; p = p->next) {
        long occ = recur_next(p, query_now + 1);
        if (occ > 0 && occ > query_now && occ <= query_now + 24 * 3600)
            if (best < 0 || occ < best) {
                best = occ;
                bestmsg = p->mesg;
            }
    }
    if (best < 0)
        return;
    delta = best - query_now;
    printf("next appointment:\n");
    printf("   [%02ld:%02ld] %s\n", delta / 3600, (delta % 3600) / 60,
           bestmsg ? bestmsg : "");
}
