PYEOF
cat >> /workspace/src/ical.c <<'CEOF'
/* ------------------------------------------------------------------ */
/* recurrence conversion                                               */
/* ------------------------------------------------------------------ */
struct rrule {
    int freq;          /* 'D','W','M','Y' or 0 */
    int interval;
    long until;
    int until_set;
    int until_isdate;
    int count;
    int count_set;
    int byday[64];
    int nbyday;
    int bymday[64];
    int nbymday;
    int bymon[64];
    int nbymon;
};

static int rrule_parse(const char *s, struct rrule *r)
{
    char buf[2048], *tok, *save = NULL;
    int badfreq = 0;
    memset(r, 0, sizeof(*r));
    r->interval = 1;
    strncpy(buf, s, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';
    for (tok = strtok_r(buf, ";", &save); tok; tok = strtok_r(NULL, ";", &save)) {
        char *v = strchr(tok, '=');
        if (!v)
            continue;
        *v++ = '\0';
        if (!strcasecmp(tok, "FREQ")) {
            if (!strcasecmp(v, "DAILY")) r->freq = 'D';
