/* compute and store the until date according to calcurse's rules */
static void set_until(item_t *it, struct rrule *r, long start)
{
    long u;
    int ud, ut, st;
    int was;

    if (!it->rpt)
        return;
    if (r->count_set && r->count > 0) {
        long occ = start, prev = start;
        int n = 0;
        was = it->rpt->until;
        it->rpt->until = 0;
        while (n < r->count) {
            occ = recur_next(it, prev + 1);
            if (occ < 0)
