    ut = (int)(u % SECS_DAY);
    st = (int)(start % SECS_DAY);
    {
        int occday = 0;
        was = it->rpt->until;
        it->rpt->until = 0;
        if (recur_next(it, ud * SECS_DAY) == ud * SECS_DAY)
            occday = 1;
        it->rpt->until = was;
