/* ------------------------------------------------------------------ */
/* import                                                              */
/* ------------------------------------------------------------------ */
enum {
    E_NONE = 0,
    E_DTSTART_BAD,
    E_NO_START,
    E_RRULE_FREQ,
    E_SUMMARY_LINE,
    E_SUMMARY_MALF,
    E_PRIO,
    E_EXDATE_LINE,
    E_EXDATE_NO_RRULE,
    E_DESC_LINE,
    E_DESC_MALF,
    E_LOC,
    E_DURATION,
    E_DTEND_TYPE,
    E_UNTIL_FMT,
    E_EXDATE_TYPE,
    E_EXDATE_BAD,
    E_BOTH,
    E_END_BEFORE,
    E_UNTERM
};

static const char *errmsg(int e, int isvtodo)
{
    switch (e) {
    case E_DTSTART_BAD:  return "invalid or malformed event start time.";
    case E_NO_START:     return "item start date not defined.";
    case E_RRULE_FREQ:   return "rrule frequency not supported.";
    case E_SUMMARY_LINE: return isvtodo ? "malformed summary." : "malformed summary line.";
    case E_SUMMARY_MALF: return isvtodo ? "malformed summary." : "malformed summary line.";
    case E_PRIO:         return "item priority is invalid (must be between 0 and 9).";
    case E_EXDATE_LINE:  return "malformed exceptions line.";
    case E_EXDATE_NO_RRULE: return "exception date, but no recurrence rule.";
    case E_DESC_LINE:    return "malformed description line.";
    case E_DESC_MALF:    return "malformed description.";
    case E_LOC:          return "only one location allowed.";
    case E_DURATION:     return "invalid duration.";
    case E_DTEND_TYPE:   return "invalid end time value type.";
    case E_UNTIL_FMT:    return "invalid until format.";
    case E_EXDATE_TYPE:  return "invalid exception date value type.";
    case E_EXDATE_BAD:   return "invalid exception.";
    case E_BOTH:         return "either end or duration.";
    case E_END_BEFORE:   return "end must be later than start.";
    case E_UNTERM:       return "The ical file seems to be malformed. The end of item was not found.";
    default:             return "invalid item.";
    }
}

/* has an unescaped ',' or ';' */
static int has_unescaped(const char *s)
{
    for (; *s; s++)
        if ((*s == ',' || *s == ';') && (s == s || 1) && !(s > (const char *)0 && s[-1] == '\\'))
            return 1;
    return 0;
}

struct imp {
    int dump;
    FILE *log;
    int nskipped;
    int napps, nevents, ntodos;
    int nl;
    char *desc;
    char *summary;
    long dtstart;
    int dtstart_isdate, dtstart_set;
    long dtend;
    int dtend_set, dtend_isdate;
    long dur;
    int dur_set;
    char rrule[2048];
    int rrule_set;
    char exdate[8192];
    int exdate_set, exdate_isdate;
    int priority, prio_set;
    int isvtodo;
    int alarm;
    int item_line;
    int loc_set;
    int err;
    int unterm;
};

static void imp_reset(struct imp *im)
{
    free(im->desc); im->desc = NULL;
    free(im->summary); im->summary = NULL;
    im->dtstart_set = 0; im->dtstart = 0; im->dtstart_isdate = 0;
    im->dtend_set = 0; im->dtend = 0; im->dtend_isdate = 0;
    im->dur_set = 0; im->dur = 0;
    im->rrule_set = 0; im->rrule[0] = '\0';
    im->exdate_set = 0; im->exdate[0] = '\0'; im->exdate_isdate = 0;
    im->priority = 0; im->prio_set = 0;
    im->alarm = 0;
    im->loc_set = 0;
    im->err = 0;
}

static void imp_seterr(struct imp *im, int e)
{
    if (im->err == E_NONE)
        im->err = e;
}

static void imp_skip(struct imp *im)
