int ical_import(const char *file, int dump, int quiet)
{
    FILE *fp;
    struct imp im;
    char line[16384];
    char raw[16384];
    int nl = 0;
    int hdr_cal = 0, hdr_ver = 0;
    char logpath[128];
    int logfd;
    int rc = 0;

    memset(&im, 0, sizeof(im));
    im.dump = dump;
    if ((fp = fopen(file, "r")) == NULL) {
        io_error(ERR_IO_INPUT, "FATAL ERROR: the input file cannot be accessed, Aborting...");
        return 1;
    }
    {
        char b[1024];
        mkdir(datadir, 0700);
        snprintf(b, sizeof(b), "%s/notes", datadir);
        mkdir(b, 0700);
    }
    strcpy(logpath, "/tmp/calcurse_log.XXXXXX");
    logfd = mkstemp(logpath);
    im.log = logfd >= 0 ? fdopen(logfd, "w") : NULL;
    if (im.log) {
        time_t t = time(NULL);
        struct tm lt;
        localtime_r(&t, &lt);
        fprintf(im.log,
"+-------------------------------------------------------------------+\n"
"| Calcurse icalendar import log.                                    |\n"
"|                                                                   |\n"
"| Import from icalendar file                                        |\n"
"|       %s\n"
"| version 2.0 at %02d/%02d/%04d %02d:%02d.                                  |\n"
"|                                                                   |\n"
"| Items which could not be imported are described below.            |\n"
"| The log line format is as follows:                                |\n"
"|                                                                   |\n"
"|       TYPE [LINE]: DESCRIPTION                                    |\n"
"|                                                                   |\n"
"| where:                                                            |\n"
"|  * TYPE is the item type, 'VEVENT' or 'VTODO'                     |\n"
"|  * LINE is the line in the import file where the item begins      |\n"
"|  * DESCRIPTION explains why the item could not be imported        |\n"
"+-------------------------------------------------------------------+\n"
"\n", file, lt.tm_mon + 1, lt.tm_mday, lt.tm_year + 1900,
                lt.tm_hour, lt.tm_min);
    }
    while (fgets(raw, sizeof(raw), fp)) {
        size_t l;
        int isdate;
        char *name, *val, *lp, *props;

        nl++;
        l = strlen(raw);
        while (l && (raw[l - 1] == '\n' || raw[l - 1] == '\r'))
            raw[--l] = '\0';
        strcpy(line, raw);
        for (;;) {
            int c = fgetc(fp);
            char buf[16384];
            if (c == EOF)
                break;
            if (c != ' ' && c != '\t') {
                ungetc(c, fp);
                break;
            }
            if (!fgets(buf, sizeof(buf), fp))
                break;
            l = strlen(buf);
            while (l && (buf[l - 1] == '\n' || buf[l - 1] == '\r'))
                buf[--l] = '\0';
            nl++;
            strcat(line, buf);
        }
        if (!strncmp(line, "BEGIN:VCALENDAR", 15)) {
            hdr_cal = 1;
            continue;
        }
        if (!strncmp(line, "END:VCALENDAR", 13))
            continue;
        if (!strncmp(line, "VERSION", 7)) {
            char *v = strchr(line, ':');
            if (v && !strcmp(v + 1, "2.0"))
                hdr_ver = 1;
            continue;
        }
        if (!hdr_cal || !hdr_ver)
            continue;
        if (!strncmp(line, "BEGIN:VEVENT", 12) || !strncmp(line, "BEGIN:VTODO", 11)) {
            im.isvtodo = (line[6] == 'V');
            im.item_line = nl;
            imp_reset(&im);
            continue;
        }
        if (!strncmp(line, "END:VEVENT", 10) || !strncmp(line, "END:VTODO", 9)) {
            if (im.isvtodo) {
                if (im.err != E_NONE) {
                    imp_skip(&im);
                    continue;
                }
                imp_commit(&im);
            } else {
                if (!im.dtstart_set) {
                    if (im.err == E_NONE)
                        im.err = E_NO_START;
                    imp_skip(&im);
                    continue;
                }
                if (im.rrule_set) {
                    struct rrule r;
                    if (rrule_parse(im.rrule, &r) < 0 && im.err == E_NONE)
                        im.err = E_RRULE_FREQ;
                }
                if (im.dtend_set && im.dur_set && im.err == E_NONE)
                    im.err = E_BOTH;
                if (im.dtend_set && !im.dtstart_isdate && im.dtend <= im.dtstart &&
                    im.err == E_NONE)
                    im.err = E_END_BEFORE;
                if (im.err != E_NONE) {
                    imp_skip(&im);
                    continue;
                }
                imp_commit(&im);
            }
            continue;
        }
        if (!strncmp(line, "BEGIN:VALARM", 12)) {
            im.alarm = 1;
            continue;
        }
        if (!strncmp(line, "END:VALARM", 10))
            continue;
        if (im.err != E_NONE)
            continue;      /* the item is already doomed */
        lp = strdup(line);
        split_prop(lp, &name, &val);
        if (!val) {
            free(lp);
            continue;
        }
        props = name;
        if (strchr(name, ';'))
            *strchr(name, ';') = '\0';
        isdate = has_param(props, "VALUE=DATE");
        if (!strcmp(name, "DTSTART")) {
            long t = parse_ical_dt(val, &isdate);
            if (t < 0 || (isdate && strchr(val, 'T')) || (!isdate && strlen(val) == 8))
                imp_seterr(&im, E_DTSTART_BAD);
            else {
                im.dtstart = t;
                im.dtstart_isdate = isdate;
                im.dtstart_set = 1;
            }
        } else if (!strcmp(name, "DTEND")) {
            long t = parse_ical_dt(val, &isdate);
            if (t < 0 || isdate != im.dtstart_isdate || (isdate && strchr(val, 'T')))
                imp_seterr(&im, E_DTEND_TYPE);
            else {
                im.dtend = t;
                im.dtend_set = 1;
                im.dtend_isdate = isdate;
            }
        } else if (!strcmp(name, "DURATION")) {
            long dv = parse_ical_dur(val);
            if (dv <= 0 || im.dtstart_isdate)
                imp_seterr(&im, E_DURATION);
            else {
                im.dur = dv;
                im.dur_set = 1;
            }
        } else if (!strcmp(name, "RRULE")) {
            struct rrule r;
            char *v = strdup(val);
            ical_unescape(v);
            if (rrule_parse(v, &r) < 0) {
                imp_seterr(&im, E_RRULE_FREQ);
            } else {
                if (r.until_set) {
                    if (r.until_isdate != im.dtstart_isdate)
                        imp_seterr(&im, E_UNTIL_FMT);
                }
                strncpy(im.rrule, v, sizeof(im.rrule) - 1);
                im.rrule_set = 1;
            }
            free(v);
        } else if (!strcmp(name, "EXDATE")) {
            if (!im.rrule_set) {
                imp_seterr(&im, E_EXDATE_NO_RRULE);
            } else if (isdate != im.dtstart_isdate) {
                imp_seterr(&im, E_EXDATE_TYPE);
            } else if (isdate && strchr(val, 'T')) {
                imp_seterr(&im, E_EXDATE_BAD);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.exdate_set)
                    strncat(im.exdate, ",", sizeof(im.exdate) - strlen(im.exdate) - 1);
                strncat(im.exdate, v, sizeof(im.exdate) - strlen(im.exdate) - 1);
                im.exdate_set = 1;
                free(v);
            }
        } else if (!strcmp(name, "SUMMARY")) {
            if (!strchr(line, ':')) {
                imp_seterr(&im, E_SUMMARY_LINE);
            } else if (has_unescaped(val)) {
                imp_seterr(&im, E_SUMMARY_MALF);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.summary)
                    free(im.summary);
                im.summary = v;
            }
        } else if (!strcmp(name, "DESCRIPTION")) {
            if (!strchr(line, ':')) {
                imp_seterr(&im, E_DESC_LINE);
            } else if (has_unescaped(val)) {
                imp_seterr(&im, E_DESC_MALF);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.desc)
                    free(im.desc);
                im.desc = v;
            }
        } else if (!strcmp(name, "COMMENT")) {
            char *v = strdup(val);
            ical_unescape(v);
            if (!im.desc) {
                char *n2 = malloc(strlen(v) + 4);
                sprintf(n2, "\n%s", v);
                im.desc = n2;
            }
            free(v);
        } else if (!strcmp(name, "PRIORITY")) {
            if (im.isvtodo) {
                int p = atoi(val);
                if (p < 0 || p > 9)
                    imp_seterr(&im, E_PRIO);
                else {
                    im.priority = p;
                    im.prio_set = 1;
                }
            }
        } else if (!strcmp(name, "LOCATION")) {
            if (im.loc_set)
                imp_seterr(&im, E_LOC);
            else
                im.loc_set = 1;
        }
        free(lp);
    }
    fclose(fp);
    if (im.item_line && !strncmp(line, "END:VCALENDAR", 13) == 0 && im.err == E_NONE &&
        im.dtstart_set)
        ;
    if (im.log)
        fclose(im.log);
    if (!hdr_cal || !hdr_ver)
        ical_warning(ERR_ICAL_HEADER,
                     "Warning: ical header malformed or wrong version number. Aborting...");
    io_save_data();
    if (!quiet) {
        printf("Import process report: %04d lines read\n", nl);
        printf("%d apps / %d events / %d todos / %d skipped\n",
               im.napps, im.nevents, im.ntodos, im.nskipped);
    }
    if (im.nskipped > 0) {
        putchar('\n');
        puts("Some items could not be imported.");
        printf("See %s for details.\n", logpath);
        rc = 1;
    }
    if (logfd >= 0 && im.nskipped == 0)
        unlink(logpath);
    return rc;
}

void import_run(void)
{
    if (ical_import(args.import_file, args.dump_imported, args.quiet))
        exit(1);
}

void export_run(void)
{
    if (args.export_format)
        pcal_export();
    else
        ical_export();
}

void gc_run(void)
{
    io_garbage_collect();
}

void status_run(void)
{
    char path[1024];
    FILE *fp;
    int pid;
    snprintf(path, sizeof(path), "%s/.calcurse.pid", datadir);
    if ((fp = fopen(path, "r")) == NULL) {
        puts("calcurse is not running");
        return;
    }
    if (fscanf(fp, "%d", &pid) != 1 || kill(pid, 0) != 0) {
        puts("calcurse is not running");
        fclose(fp);
        return;
    }
    printf("calcurse is running (pid %d)\n", pid);
    fclose(fp);
}

void daemon_run(void)
{
    exit(0);
}
