                imp_seterr(&im, E_RRULE_FREQ);
            } else {
                if (r.until_set) {
                    if (r.until_isdate != im.dtstart_isdate)
                        imp_seterr(&im, E_UNTIL_FMT);
                }
                strncpy(im.rrule, v, sizeof(im.rrule) - 1);
                im.rrule_set = 1;
            }
            free(v);
        } else if (!strcmp(name, "EXDATE")) {
            if (!im.rrule_set) {
                imp_seterr(&im, E_EXDATE_NO_RRULE);
            } else if (isdate != im.dtstart_isdate) {
                imp_seterr(&im, E_EXDATE_TYPE);
            } else if (isdate && strchr(val, 'T')) {
                imp_seterr(&im, E_EXDATE_BAD);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.exdate_set)
                    strncat(im.exdate, ",", sizeof(im.exdate) - strlen(im.exdate) - 1);
                strncat(im.exdate, v, sizeof(im.exdate) - strlen(im.exdate) - 1);
                im.exdate_set = 1;
                free(v);
            }
        } else if (!strcmp(name, "SUMMARY")) {
            if (!strchr(line, ':')) {
                imp_seterr(&im, E_SUMMARY_LINE);
            } else if (has_unescaped(val)) {
                imp_seterr(&im, E_SUMMARY_MALF);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.summary)
