            if (!strchr(line, ':')) {
                imp_seterr(&im, E_DESC_LINE);
            } else if (has_unescaped(val)) {
                imp_seterr(&im, E_DESC_MALF);
            } else {
                char *v = strdup(val);
                ical_unescape(v);
                if (im.desc)
                    free(im.desc);
                im.desc = v;
            }
        } else if (!strcmp(name, "COMMENT")) {
            char *v = strdup(val);
            ical_unescape(v);
            if (!im.desc) {
                char *n2 = malloc(strlen(v) + 4);
                sprintf(n2, "\n%s", v);
                im.desc = n2;
            }
            free(v);
        } else if (!strcmp(name, "PRIORITY")) {
            if (im.isvtodo) {
                int p = atoi(val);
                if (p < 0 || p > 9)
                    imp_seterr(&im, E_PRIO);
                else {
                    im.priority = p;
                    im.prio_set = 1;
                }
            }
