    if (im.log)
        fclose(im.log);
    if (!hdr_cal || !hdr_ver)
        ical_warning(ERR_ICAL_HEADER,
                     "Warning: ical header malformed or wrong version number. Aborting...");
    io_save_data();
    if (!quiet) {
        printf("Import process report: %04d lines read\n", nl);
        printf("%d apps / %d events / %d todos / %d skipped\n",
               im.napps, im.nevents, im.ntodos, im.nskipped);
    }
    if (im.nskipped > 0) {
        putchar('\n');
        puts("Some items could not be imported.");
        printf("See %s for details.\n", logpath);
        rc = 1;
    }
    if (logfd >= 0 && im.nskipped == 0)
        unlink(logpath);
    return rc;
}

